GimCorpus.put(119,0,[[1,2,"וְהִנֵּה אִישׁ בָּא מִן הַמַּחֲנֶה. יֵשׁ בַּפְּסִקְתָּא שֶׁזֶּה דּוֹאֵג וְאֵינוֹ מְיֻשָּׁב עַל לִבִּי:",1,0],[1,9,"אֲחָזַנִי הַשָּׁבָץ. (תרגום:) ״אֲחָדַנִי רְתִיתָא״. וּמִדְרַשׁ אַגָּדָה (ראה ילקוט שמעוני רמז קמא): מִשּׁוּם עָוֹן הַכֹּהֲנִים שֶׁהָרַג, וְכָתוּב בָּהֶן (שמות כח:ד): ״כְּתֹנֶת תַּשְׁבֵּץ״:",1,0],[1,9,"כִּי כָל עוֹד נַפְשִׁי בִּי. מַהֵר וּמוֹתְתֵנִי, טוֹב לִי שֶׁתְּמוֹתְתֵנִי אַתָּה, וְאַל יַהַרְגוּנִי אֵלֶּה וְיִתְעַלְּלוּ בִי:",2,0],[1,10,"וְאֶצְעָדָה אֲשֶׁר עַל זְרֹעוֹ. (תרגום:) ״וְטוֹטַפְתָּא דְעַל דְּרָעֵיהּ״:",1,0],[1,16,"דָּמְךָ עַל רֹאשֶׁךָ. (תרגום:) ״חוֹבַת קְטוֹלָךְ תְּהֵי בְרֵישָׁךְ״, אֵין עוֹנֶשׁ בְּמִיתָתְךָ אֶלָּא לְעַצְמְךָ:",1,0],[1,18,"וַיֹּאמֶר לְלַמֵּד בְּנֵי יְהוּדָה קָשֶׁת. וַיֹּאמֶר דָּוִד, מֵעַתָּה שֶׁנָּפְלוּ גִבּוֹרֵי יִשְׂרָאֵל, צְרִיכִין בְּנֵי יְהוּדָה לְלַמְּדָם מִלְחָמָה וְלִמְשׁוֹךְ בְּקֶשֶׁת:",1,0],[1,18,"הִנֵּה כְתוּבָה עַל סֵפֶר הַיָּשָׁר. הֲלֹא הִיא כְּתוּבָה עַל סֵפֶר בְּרֵאשִׁית שֶׁהִיא סֵפֶר יְשָׁרִים, אַבְרָהָם יִצְחָק וְיַעֲקֹב, וְהֵיכָן רְמִיזָא, (בראשית מט:ח): ״יָדְךָ בְּעֹרֶף אוֹיְבֶיךָ״, אֵיזוֹ הִיא מִלְחָמָה שֶׁמְּכַוֵּן בָּהּ יָדוֹ כְּנֶגֶד פַּדַּחְתּוֹ שֶׁהוּא מוּל עָרְפּוֹ, הֱוֵי אוֹמֵר זֶה קֶשֶׁת:",2,0],[1,19,"הַצְּבִי יִשְׂרָאֵל עַל בָּמוֹתֶיךָ חָלָל. מַצְבָּן שֶׁל יִשְׂרָאֵל, עַל תֹּקֶף מָעֻזְּכֶם נְפַלְתֶּם חֲלָלִים, כֵּן תִּרְגֵּם יוֹנָתָן:",1,0],[1,21,"הָרֵי בַגִּלְבֹּעַ. הֶהָרִים שֶׁבְּגִלְבֹּעַ:",1,0],[1,21,"וּשְׂדֵי תְרוּמוֹת. (תרגום:) ״לָא תְּהֵי בְכוֹן עֲלָלָא כְּמֵיסַת דִּיעַבְּדוּן מִנֵּיהּ חַלְתָּא״:",2,0],[1,21,"כִּי שָׁם נִגְעַל מָגֵן גִּבּוֹרִים. מָגִינֵּי עוֹר הָיוּ לָהֶם, וּכְשֶׁיּוֹצְאִים לַמִּלְחָמָה מוֹשְׁחִין אוֹתָן בְּשֶׁמֶן, כְּדֵי שֶׁיְּהֵא כְּלִי זַיִן הַמַּכֶּה עָלָיו מַחְלִיק, כְּמָה דְאַתְּ אָמַר (ישעיהו כא:ה): ״קוּמוּ הַשָּׂרִים מִשְׁחוּ מָגֵן״. וְכָאן כָּךְ הָיָה מְקוֹנֵן הַקִּינָה, שָׁם נִגְעַל מָגֵן גִּבּוֹרִים, פָּלַט שׁוּמְנוֹ וְלֹא נִדְבַּק בּוֹ, וְנַעֲשָׂה כְּאִלּוּ לֹא נִמְשַׁח בְּשֶׁמֶן. כָּל ׳הַגְעָלָה׳ לְשׁוֹן דָּבָר הַפּוֹלֵט מַה שֶּׁנּוֹתְנִין בּוֹ, כְּמוֹ (איוב כא:י): ״שׁוֹרוֹ עִבַּר וְלֹא יַגְעִיל״:",3,0],[1,22,"לֹא נָשׂוֹג אָחוֹר. לֹא הָיָה רָגִיל לִהְיוֹת נָסוֹג אָחוֹר:",1,0],[1,23,"מִנְּשָׁרִים קַלּוּ. לַעֲשׂוֹת רְצוֹן בּוֹרְאָם:",1,0],[1,24,"הַמַּלְבִּשְׁכֶם שָׁנִי עִם עֲדָנִים. (תרגום:) ״דַּהֲוָה מַלְבֵּישׁ לְכוֹן לְבוּשֵׁי צִבְעוֹנִין וּמוֹבִיל לְכוֹן תַּפְנוּקִין״:",1,0],[1,25,"עַל בָּמוֹתֶיךָ חָלָל. (תרגום:) ״עַל בֵּית תּוּקְפָּךְ אִיתְקְטַלְתָּא״:",1,0],[1,27,"כְּלֵי מִלְחָמָה. שָׁאוּל וִיהוֹנָתָן, שֶׁהָיוּ כְּלֵי זַיִן שֶׁל יִשְׂרָאֵל:",1,0],[2,8,"לָקַח אֶת אִישׁ בֹּשֶׁת. מִקְרָא הָיָה דוֹרֵשׁ שֶׁעֲתִידִין שְׁנֵי מְלָכִים לַעֲמוֹד מִבִּנְיָמִן, שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַעֲקֹב (בראשית לה:יב) ״וּמְלָכִים מֵחֲלָצֶיךָ יֵצֵאוּ״, וּכְבָר נוֹלְדוּ כָּל בָּנָיו חוּץ מִבִּנְיָמִין:",1,0],[2,16,"חֶלְקַת הַצּוּרִים. (תרגום:) ״אַחְסָנַת קְטִילַיָּא״, עַל שֵׁם הַחֲרָבוֹת, כְּמָה דְאַתְּ אָמַר (תהלים פט:מד): ״אַף תָּשִׁיב צוּר חַרְבּוֹ״:",1,0],[2,23,"אֶל הַחֹמֶשׁ. כְּמוֹ דֹפֶן חֲמִישִׁית, מְקוֹם שֶׁמָּרָה וְכָבֵד תְּלוּיִין שָׁם (סנהדרין מט א) וְיוֹנָתָן תִּרְגֵּם: אֶל הַחֹמֶשׁ, ״בִּסְטַר יַרְכֵיהּ״:",1,0],[2,23,"וַיָּמָת תַּחְתָּו. (תרגום:) ״וּמִית בְּאַתְרֵיהּ״:",2,0],[2,27,"לוּלֵא דִבַּרְתָּ. אִם דִּבַּרְתָּ כֵּן, ׳לוּלֵא׳ כְּמוֹ ׳לוּ׳ וְעוֹד יֵשׁ לְפָתְרוֹ כְּמַשְׁמָעוֹ, לוּלֵא דִבַּרְתָּ מַה שֶּׁאָמַרְתָּ (לעיל פסוק יד): ״יָקוּמוּ נָא הַנְּעָרִים וִישַׂחֲקוּ״:",1,0],[2,29,"הַבִּתְרוֹן. שֵׁם מָחוֹז:",1,0],[2,30,"תִּשְׁעָה עָשָׂר אִישׁ וַעֲשָׂהאֵל. וַהֲלֹא עֲשָׂהאֵל בִּכְלַל עַבְדֵי דָוִד, וְלָמָּה יָצָא, שֶׁהָיָה שָׁקוּל כְּנֶגֶד כֻּלָּם, וְכֵן (יהושע ב:א): ״לְכוּ רְאוּ אֶת הָאָרֶץ וְאֶת יְרִיחוֹ״; וְכֵן (מלכים א יא:א): ״וְהַמֶּלֶךְ שְׁלֹמֹה אָהַב נָשִׁים נָכְרִיּוֹת רַבּוֹת וְאֶת בַּת פַּרְעֹה״:",1,0],[3,3,"וּמִשְׁנֵהוּ כִלְאָב. וּבְמָקוֹם אַחֵר הוּא קוֹרֵא אוֹתוֹ וּמִשְׁנֵהוּ דָּנִיאֵל, וְלָמָּה נִקְרָא שְׁמוֹ כִּלְאָב, אָמַר רַבִּי יִצְחָק: שֶׁהָיוּ לֵיצָנֵי הַדּוֹר אוֹמְרִים, מִנָּבָל הָיְתָה אֲבִיגַיִל מְעֻבֶּרֶת, נֶהְפַּךְ קְלַסְתֵּרוֹ וְנִדְמָה לְאָבִיו. וְרַבּוֹתֵינוּ אָמְרוּ (ברכות ד א): שֶׁהָיָה מַכְלִים פְּנֵי מְפִיבֹשֶׁת בַּהֲלָכָה:",1,0],[3,5,"לְעֶגְלָה. זוֹ מִיכַל, שֶׁהָיְתָה חֲבִיבָה עָלָיו, וְכֵן הוּא אוֹמֵר (שופטים יד:יח): ״לוּלֵא חֲרַשְׁתֶּם בְּעֶגְלָתִי״. וְהַכְּתִיב (שמואל ב ו:כג): ״וּלְמִיכַל בַּת שָׁאוּל לֹא הָיָה לָהּ וָלָד עַד יוֹם מוֹתָהּ״, עַד יוֹם מוֹתָהּ לֹא הָיָה לָהּ מֵאוֹתוֹ מַעֲשֶׂה וְאֵילַךְ, קוֹדֶם אוֹתוֹ מַעֲשֶׂה הֲוֵי לָהּ:",1,0],[3,6,"הָיָה מִתְחַזֵּק. בְּכָל כֹּחַ עַל בֵּית שָׁאוּל לְהַעֲמִיד מַלְכוּתוֹ:",1,0],[3,8,"הֲרֹאשׁ כֶּלֶב אָנֹכִי אֲשֶׁר לִיהוּדָה. כְּלוּם אֲנִי חָשׁוּב אֲפִלּוּ כְּרֹאשׁ שׁוֹמֵר הַכְּלָבִים אֲשֶׁר לְדָוִד, אַךְ לְפִי הַנִּקּוּד, שֶׁהַטַּעַם תַּחַת ׳הֲרֹאשׁ׳, וְ׳כֶלֶב אָנֹכִי׳ מֻקָּף בְּמַקָּף, כָּךְ פֵּרוּשׁוֹ: הֲרֹאשׁ, וְכִי אֶחְפֹּץ לִהְיוֹת רֹאשׁ בְּבֵיתֶךָ, טוֹב לִי לִהְיוֹת כֶּלֶב וְהֶדְיוֹט בְּבֵית דָּוִד, וְכֵן תִּרְגֵּם יוֹנָתָן:",1,0],[3,8,"הַיּוֹם אֶעֱשֶׂה חֶסֶד. מֵעַתָּה נָאֶה לִי לַעֲשׂוֹת חֶסֶד עִם בֵּית שָׁאוּל וְעִם כָּל אוֹהֲבָיו, כַּאֲשֶׁר עָשִׂיתִי עַד הֵנָּה וְלֹא הִמְצֵיתִיךָ בְּיַד דָּוִד:",2,0],[3,12,"תַּחְתָּו לֵאמֹר. (תרגום:) ״מֵאַתְרֵיהּ לְמֵימַר מְקַיְּמְנָא בְּמָאן דַּעֲבַד אַרְעָא״:",1,0],[3,12,"לְמִי אָרֶץ. לְשׁוֹן שְׁבוּעָה, בְּמִי שֶׁהָאָרֶץ שֶׁלּוֹ. דָּבָר אַחֵר: תַּחְתָּיו, שְׁמוֹ הִזְכִּיר תְּחִלָּה בָּאִגֶּרֶת, וְאַחַר כָּךְ הִזְכִּיר שֵׁם דָּוִד, וּלְכָךְ נֶעֱנַשׁ, כָּתַב: מִמֶּנִּי אַבְנֵר שַׂר צְבָא יִשְׂרָאֵל, לְדָוִד מֶלֶךְ יִשְׂרָאֵל, שָׁלוֹם:",2,0],[3,12,"לְמִי אָרֶץ. לְמִי שֶׁהַמַּלְכוּת הָגוּן לוֹ, אֲנִי שׁוֹלֵחַ לוֹ לֵאמֹר: כָּרְתָה בְרִיתְךָ וְגוֹ׳:",3,0],[3,13,"לִפְנֵי הֲבִיאֲךָ. לִפְנֵי רְאוֹתְךָ פָנַי, הֲבִיאֲךָ אֶת מִיכַל:",1,0],[3,15,"מֵעִם אִישׁ. תִּרְגֵּם יוֹנָתָן: ״מִלְּוַת בַּעְלָהּ״:",1,0],[3,16,"הָלוֹךְ וּבָכֹה. עַל מִצְוָה הַהוֹלֶכֶת מִמֶּנּוּ, שֶׁכָּל אוֹתָן הַשָּׁנִים נָעַץ חֶרֶב בֵּינוֹ לְבֵינָהּ בַּמִּטָּה, וְלֹא נִכְשַׁל בָּהּ:",1,0],[3,17,"וּדְבַר אַבְנֵר הָיָה. קדֶם לָכֵן:",1,0],[3,18,"אָמַר אֶל דָּוִד. עַל דָּוִד, וְאֵינוֹ זָז מִמַּשְׁמָעוּת אֶל:",1,0],[3,22,"מֵהַגְּדוּד. פָּשְׁטוּ בַּגְּדוּד, לִשְׁלוֹל עַל הָאוֹיֵב:",1,0],[3,26,"מִבּוֹר הַסִּרָה. שֵׁם מָקוֹם וְרַבּוֹתֵינוּ אָמְרוּ (סנהדרין מט א): בּוֹר וְסִירָה גָּרְמוּ לוֹ לְאַבְנֵר שֶׁיֵּהָרֵג, עַל שֶׁלֹּא הֶחֱזִיק דִּבְרֵי דָוִד בְּצַפַּחַת הַמַּיִם אֲשֶׁר לָקַח מְרַאֲשׁוֹתָיו שֶׁל שָׁאוּל, וְגַם עַל כְּנַף הַמְּעִיל שֶׁל שָׁאוּל אָמַר שֶׁמָּא אֶחָד מִן הַסִּירִים נֶאֱחַז בּוֹ וּקְרָעוֹ:",1,0],[3,27,"אֶל תּוֹךְ הַשַּׁעַר. לִפְנֵי סַנְהֶדְרִין, לְהִשָּׁפֵט עַל דַּם עֲשָׂהאֵל אָחִיו:",1,0],[3,27,"בַּשֶּׁלִי. בִּשְׁגָגָה, שֶׁלֹּא הֵבִין אַבְנֵר שֶׁבְּלִבּוֹ לְהָרְגוֹ, וְסָרֵס הַמִּקְרָא, וַיַּטֵּהוּ יוֹאָב בַּשֶּׁלִי, אֶל תּוֹךְ הַשַּׁעַר לְדַבֵּר אִתּוֹ:",2,0],[3,29,"יָחוּלוּ. יָנוּחוּ, יָחוּלוּ דְּמֵי אַבְנֵר עַל מִקְרָא שֶׁלְּפָנָיו הוּא מוּסָב, שֶׁאָמַר ׳נָקִי אָנִי וּמַמְלַכְתִּי מִדְּמֵי אַבְנֵר׳, יָחוּלוּ דָּמָיו עַל רֹאשׁ יוֹאָב, ׳דְּמֵי׳ הַנִּזְכָּרִים בַּמִּקְרָא שֶׁלְּפָנָיו:",1,0],[3,29,"וּמַחֲזִיק בַּפֶּלֶךְ. נִשְׁעָן עַל מַקְלוֹ מֵחֲמַת חוֹלִי הָרַגְלַיִם:",2,0],[3,30,"הָרְגוּ לְאַבְנֵר. כְּמוֹ אֶת אַבְנֵר, וְדוֹמֶה לוֹ (ישעיהו לח:יד): ״עָשְׁקָה לִי עָרְבֵנִי״, עָשְׁקָה אוֹתִי; וְכֵן (במדבר יב:יג): ״רְפָא נָא לָהּ״, רְפָא אוֹתָהּ; וּכְמוֹהוּ (דברי הימים ב יז:ז): ״שָׁלַח לְשָׂרָיו לְבֶן חַיִל לְעוֹבַדְיָה וְגוֹ׳ לְלַמֵּד בְּעָרֵי יְהוּדָה״, וּפִתְרוֹנוֹ, שָׁלַח אֶת שָׂרָיו אֶת בֶּן חַיִל:",1,0],[3,33,"הַכְּמוֹת נָבָל. הַכְּמוֹת רָשָׁע בְּחֶרֶב:",1,0],[3,34,"יָדֶיךָ לֹא אֲסוּרוֹת. הָיוּ וְאֵיךְ נָפַל גִּבּוֹר כְּמוֹתְךָ לִפְנֵי בְּנֵי עַוְלָה:",1,0],[3,35,"לְהַבְרוֹת. לְשׁוֹן סְעוּדָה:",1,0],[3,39,"וְאָנֹכִי הַיּוֹם רַךְ. (תרגום:) ״וַאֲנָא יוֹמָא דֵין הֶדְיוֹט וּמְרַבֵּי לְמַלְכָּא״:",1,0],[4,2,"הָיוּ בֶן שָׁאוּל. הָיוּ לְבֶן שָׁאוּל, כְּמוֹ (שמואל א יג:ח): ״לַמּוֹעֵד אֲשֶׁר שְׁמוּאֵל״, אֲשֶׁר לִשְׁמוּאֵל:",1,0],[4,3,"וַיִּבְרְחוּ הַבְּאֵרֹתִים. כְּשֶׁמֵּת שָׁאוּל, שֶׁעָזְבוּ בְּנֵי יִשְׂרָאֵל הֶעָרִים שֶׁסְּבִיבוֹת פְּלִשְׁתִּים, כְּמוֹ שֶׁאָמוּר לְמַעְלָה, אָז בָּרְחוּ הַבְּאֵרוֹתִים:",1,0],[4,4,"וְלִיהוֹנָתָן בֶּן שָׁאוּל. מוֹנֶה וְהוֹלֵךְ אֵיךְ נִשְׁבַּת מַלְכוּת מִבֵּית שָׁאוּל, הוּא וּבָנָיו נֶהֶרְגוּ, וְזֶה הַנִּשְׁאָר, הֲרָגוּהוּ עַל מִשְׁכָּבוֹ, וּבְנוֹ שֶׁל יְהוֹנָתָן נָפַל וַיִּפָּסֵחַ:",1,0],[4,4,"נְכֵה רַגְלָיִם. שְׁבוּר רַגְלַיִם:",2,0],[4,6,"וְהֵנָּה בָּאוּ עַד תּוֹךְ הַבַּיִת. עִם תַּגָּרִים לוֹקְחֵי חִטִּים:",1,0],[4,10,"לְתִתִּי לוֹ בְּשׂוֹרָה. אֲשֶׁר דִּמָּה לְשַׂמְּחֵנִי, לְמַעַן תִּתִּי לוֹ שְׂכַר בְּשׂוֹרָתוֹ:",1,0],[5,6,"אֶל הַיְבוּסִי. מְצוּדַת צִיּוֹן נִקְרְאָה יְבוּס, וּמִזַּרְעוֹ שֶׁל אֲבִימֶלֶךְ הָיוּ, וְהָיוּ לָהֶם שְׁנֵי צְלָמִים, אֶחָד עִוֵּר, וְאֶחָד פִּסֵּחַ, שֶׁנַּעֲשׂוּ עַל שֵׁם יִצְחָק וְיַעֲקֹב, וּבְפִיהֶם הַשְּׁבוּעָה שֶׁנִּשְׁבַּע אַבְרָהָם לַאֲבִימֶלֶךְ, וּלְכָךְ לֹא הוֹרִישׁוּם כְּשֶׁלָּכְדוּ אֶת יְרוּשָׁלַיִם, לֹא לָכְדוּ אֶת הַמְּצוּדָה, כְּמוֹ שֶׁנֶּאֱמַר (יהושע טו:סג): ״וְאֶת הַיְבוּסִי יֹשֵׁב יְרוּשָׁלַיִם לֹא יָכְלוּ יוֹשְׁבֵי יְהוּדָה לְהוֹרִישָׁם״, וְתַנְיָא אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי: יְכוֹלִין הָיוּ, אֶלָּא שֶׁלֹּא הָיוּ רַשָּׁאִין (ספרי ראה יב יז):",1,0],[5,6,"וַיֹּאמֶר לְדָוִד. מִי שֶׁאָמַר:",2,0],[5,6,"הָעִוְרִים וְהַפִּסְחִים. הֵם עֲבוֹדַת כּוֹכָבִים שֶׁלָּהֶם:",3,0],[5,8,"כָּל מַכֵּה יְבוּסִי וְיִגַּע בַּצִּנּוֹר. (תרגום:) ״כָּל דְיִקְטַל יְבוּסָאָה וְיִשְׁרֵי לְמִכְבַּשׁ כְּרַכָּא״:",1,0],[5,8,"וְאֶת הַפִּסְחִים. וְיַכֶּה גַּם אֶת הַפִּסְחִים וְאֶת הָעִוְרִים שְׂנוּאֵי נֶפֶשׁ דָּוִד:",2,0],[5,8,"עַל כֵּן יֹאמְרוּ. עַל אֲשֶׁר אוֹמְרִים: עִוֵּר וּפִסֵּחַ. בְּעוֹד שֶׁהָעִוֵּר וְהַפִּסֵּחַ יִהְיֶה בְּכָאן:",3,0],[5,8,"לֹא יָבֹא וְגוֹ׳. יָבֹא דָוִד הֵנָּה הֲרֵי זֶה מִקְרָא קָצָר, שֶׁאָמַר כָּל מַכֵּה יְבוּסִי וְיִגַּע בַּצִּנּוֹר, וְלֹא פֵּרֵשׁ מַה יַּעֲשֶׂה לוֹ, וּבְדִבְרֵי הַיָּמִים (דברי הימים א יא:ו) פֵּרֵשׁ: ״כָּל מַכֵּה יְבוּסִי בָּרִאשׁוֹנָה יִהְיֶה לְרֹאשׁ וּלְשַׂר״; וְדוֹמֶה לָזֶה (בראשית ד:טו): ״לָכֵן כָּל הֹרֵג קַיִן״, וְלֹא פֵּרֵשׁ מַה יַּעֲשֶׂה לוֹ, אֲבָל מֵעַצְמוֹ הוּא נִשְׁמָע לְשׁוֹן גְּעָרָה וּנְזִיפָה:",4,0],[5,8,"וְיִגַּע בַּצִּנּוֹר. לְשׁוֹן גֹּבַהּ הַמִּגְדָּל, כִּי שָׁם הָיוּ נְתוּנִים הַצְּלָמִים שֶׁלָּהֶם, וּבִימֵי דָוִד כְּבָר עָבְרוּ הַדּוֹרוֹת שֶׁהֻזְכְּרוּ בַּשְּׁבוּעָה:",5,0],[5,9,"מִן הַמִּלּוֹא וָבָיְתָה. הֶקֵּף חוֹמָה נְמוּכָה, וּמְמַלְּאִין אוֹתָהּ עָפָר, וְגֹבַהּ הַתֵּל בָּאֶמְצַע, וּמְשַׁפֵּעַ וְהוֹלֵךְ לְכָל רוּחַ, הוּא קָרוּי מִלּוֹא, וְעָלָיו בָּנָה דָוִד בָּתִּים, וְאוֹתוֹ הַמִּלּוֹא הָיָה סָבִיב לַמְּצוּדָה:",1,0],[5,12,"וַיֵּדַע דָּוִד. בִּרְאוֹתוֹ כָּל מַעֲשָׂיו מַצְלִיחִין, וּמַלְכֵי הַגּוֹיִם שׁוֹלְחִין לוֹ מִנְחָה:",1,0],[5,18,"וַיִּנָּטְשׁוּ. וַיִּתְפַּשְּׁטוּ:",1,0],[5,20,"בְּבַעַל פְּרָצִים. מִישׁוֹר פְּרָצִים:",1,0],[5,20,"כְּפֶרֶץ מָיִם. כְּמַיִם הַפּוֹרְצִים גְּדוּדֵי הַשָּׂפָה:",2,0],[5,21,"וַיִּשָּׂאֵם דָּוִד. (תרגום:) ״וְאוֹקִידִינוּן דָּוִד וְגַבְרוֹהִי״:",1,0],[5,22,"בְּעֵמֶק רְפָאִים. אֵצֶל יְרוּשָׁלַיִם הִיא, בְּסֵפֶר יְהוֹשֻׁעַ (טו:ח):",1,0],[5,23,"מִמּוּל בְּכָאִים. (תרגום:) ״מִקְּבֵל אִילָנַיָּא״:",1,0],[5,24,"אֶת קוֹל צְעָדָה בְּרָאשֵׁי הַבְּכָאִים. הֵם מַלְאָכִים הַצּוֹעֲדִים בְּרָאשֵׁי הָאִילָנוֹת, אֲשֶׁר אֲנִי שׁוֹלֵחַ לְעֶזְרָתֶךָ:",1,0],[5,24,"אָז תֶּחֱרָץ. תָּרִים קוֹל מִלְחָמָה וְאַבְחַת חֶרֶב, גלפי״ד בלע״ז, וְכֵן (שמות יא:ז): ״לֹא יֶחֱרַץ כֶּלֶב לְשׁוֹנוֹ״:",2,0],[6,1,"וַיֹּסֶף עוֹד דָּוִד. לֶאֱסֹף:",1,0],[6,1,"אֶת כָּל בָּחוּר בְּיִשְׂרָאֵל שְׁלֹשִׁים אָלֶף. לְפִי שֶׁנֶּאֶסְפוּ עָלָיו כְּשֶׁהִמְלִיכוּהוּ בְּחֶבְרוֹן, וְזוֹ הָיְתָה אֲסִיפָה שְׁנִיָּה, לְכָךְ נֶאֱמַר וַיֹּסֶף עוֹד:",2,0],[6,2,"מִבַּעֲלֵי יְהוּדָה. הִיא קִרְיַת יְעָרִים, כְּמוֹ שֶׁנֶּאֱמַר בִּיהוֹשֻׁעַ (יהושע טו:ט): ״וְתָאַר הַגְּבוּל וְעָלָה בַּעֲלָה הִיא קִרְיַת יְעָרִים״, וְכֵן בְּדִבְרֵי הַיָּמִים (דברי הימים א יג:ו): ״וַיַּעַל דָּוִד וְכָל יִשְׂרָאֵל בַּעֲלָתָה הִיא קִרְיַת יְעָרִים״. וּ׳בַעַל׳ לְשׁוֹן ׳מִישׁוֹר׳:",1,0],[6,2,"וַיָּקָם וַיֵּלֶךְ דָּוִד וְגוֹ׳ מִבַּעֲלֵי יְהוּדָה. שֶׁנֶּאֶסְפוּ שָׁם לְהַעֲלוֹת מִשָּׁם אֵת הָאָרוֹן וְגוֹ׳:",2,0],[6,2,"אֲשֶׁר נִקְרָא שֵׁם שֵׁם. אֲשֶׁר נִקְרָא לוֹ לָאָרוֹן שֵׁם, וּמַהוּ הַשֵּׁם, שֶׁהָיָה שֵׁם ה׳ צְבָאוֹת עָלָיו:",3,0],[6,3,"אֶל עֲגָלָה חֲדָשָׁה. טָעָה בְּדָבָר שֶׁאֲפִילוּ תִינוֹקוֹת שֶׁל בֵּית רַבָּן יוֹדְעִין אוֹתוֹ, ״כִּי עֲבֹדַת הַקֹּדֶשׁ עֲלֵיהֶם בַּכָּתֵף יִשָּׂאוּ״ (במדבר ז:ט), וּלְפִי שֶׁאָמַר (תהלים קיט:נד): ״זְמִירוֹת הָיוּ לִי חֻקֶּיךָ בְּבֵית מְגוּרָי״, נֶעֱנַשׁ לָבֹא לִידֵי כָּךְ, וּמֵת עֻזָּא עַל יָדוֹ, לְפִיכָךְ כְּשֶׁהֱבִיאוּ מִבֵּית עוֹבֵד, הֱבִיאוּ בַּכָּתֵף, שֶׁנֶּאֱמַר (דברי הימים א טו:יב-יג): ״וַיֹּאמֶר לָהֶם אַתֶּם רָאשֵׁי הָאָבוֹת לַלְוִיִּם הִתְקַדְּשׁוּ אַתֶּם וַאֲחֵיכֶם וְהַעֲלִיתֶם אֶת אֲרוֹן וְגוֹ׳. כִּי לְמִבָּרִאשׁוֹנָה לֹא אַתֶּם פָּרַץ ה׳ אֱלֹהֵינוּ בָּנוּ כִּי לֹא דְרַשְׁנוּהוּ כַּמִּשְׁפָּט״:",1,0],[6,4,"עִם אֲרוֹן הָאֱלֹהִים. הֲרֵי זֶה מִקְרָא קָצָר, וְהֵם בָּאִים עִם אֲרוֹן הָאֱלֹהִים:",1,0],[6,5,"בְּכָל עֲצֵי בְרוֹשִׁים. שֶׁמְּתַקְּנִים מֵהֶם כְּלֵי זֶמֶר:",1,0],[6,6,"כִּי שָׁמְטוּ הַבָּקָר. כִּי שְׁמָטוּהוּ הַבָּקָר וְנִעְנְעוּהוּ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״אֲרֵי מְרָגוּהִי תּוֹרַיָּא״, כְּמוֹ שֶׁמְּתַרְגֵּם (דברים יט:ה): ״וְנִדְּחָה יָדוֹ בַגַּרְזֶן״, ״וְתִתְמְרִיג יְדֵיהּ בְּפַרְזְלָא״:",1,0],[6,7,"עַל הַשַּׁל. עַל הַשְּׁגָגָה, שֶׁהָיָה לוֹ לִדְרֹשׁ קַל וָחֹמֶר, נוֹשְׂאָיו נָשָׂא בַּיַּרְדֵּן, הוּא עַצְמוֹ לֹא כָּל שֶׁכֵּן:",1,0],[6,10,"עוֹבֵד אֱדוֹם. לֵוִי הָיָה, כְּמוֹ שֶׁכָּתוּב בְּדִבְרֵי הַיָּמִים (דברי הימים א טו:יח), ״וּמִן הַשּׁוֹעֲרִים הָיָה״ (שם):",1,0],[6,11,"וַיְבָרֶךְ ה׳ וְגוֹ׳. אִשְׁתּוֹ וּשְׁמוֹנֶה כַּלּוֹתֶיהָ יָלְדוּ שִׁשָּׁה בָּנִים בְּכֶרֶס אֶחָד, שֶׁנֶּאֱמַר (דברי הימים א כו:ה): ״פְעֻלְתַּי הַשְּׁמִינִי״, ״שִׁשִּׁים וּשְׁנַיִם לְעֹבֵד אֱדוֹם״:",1,0],[6,14,"מְכַרְכֵּר. מְרַקֵּד:",1,0],[6,14,"אֵפוֹד בָּד. מְעִיל בּוּץ, פורציינ״ט בלע״ז, וְיוֹנָתָן תִּרְגֵּם: ״כַּרְדּוֹט״, וְכֵן תִּרְגֵּם יוֹנָתָן ׳מְעִילִים׳ דְּתָמָר אֲחוֹת אַבְשָׁלוֹם (שמואל ב יג:יח), ״כַּרְדּוֹטִין״:",2,0],[6,19,"וְאֶשְׁפָּר. אֶחָד מִשִּׁשָּׁה בְּפַר (פסחים לו ב):",1,0],[6,19,"אֲשִׁישָׁה אֶחָת. גַּרְבָּא דְּחַמְרָא (שם):",2,0],[6,20,"אַחַד הָרֵקִים. (תרגום:) ״חַד מִן סְרִיקַיָּא״:",1,0],[6,22,"וּנְקַלֹּתִי עוֹד. לְפָנָיו, יוֹתֵר מִזֹּאת שֶׁהֲקִלּוֹתִי בְּעַצְמִי עַתָּה:",1,0],[6,22,"עִמָּם אִכָּבֵדָה. אֵינָם מְבַזִּין אוֹתִי, אֶלָּא חָשׁוּב אֲנִי בְּעֵינֵיהֶם עַל זֹאת:",2,0],[6,23,"לֹא הָיָה לָהּ יָלֶד. מֵאוֹתוֹ הַיּוֹם וָהָלְאָה:",1,0],[7,1,"וַה׳ הֵנִיחַ לוֹ. אָמַר, הֲרֵי נִתְקַיֵּם (דברים יב:י): ״וְהֵנִיחַ לָכֶם מִכָּל אֹיְבֵיכֶם וְגוֹ׳״, מַה כְּתִיב אַחֲרָיו, ״וְהָיָה הַמָּקוֹם אֲשֶׁר יִבְחַר וְגוֹ׳״, מֵעַתָּה עָלֵינוּ לִבְנוֹת בֵּית הַבְּחִירָה:",1,0],[7,4,"וַיְהִי בַּלַּיְלָה הַהוּא. אָמַר רַבִּי חֲנִינָא בַּר פָּפָּא: אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְנָתָן, הָאָדָם הַזֶּה שֶׁאֲנִי מְשַׁלֶּחֲךָ אֶצְלוֹ, מָהִיר הוּא, שֶׁמָּא יִשְׂכּוֹר פּוֹעֲלִים וְנִמְצֵאתִי מַפְסִידוֹ, מַהֵר וֶאֱמוֹר לוֹ, לֹא אַתָּה תִבְנֶה הַבַּיִת. רַבִּי סִימוֹן אוֹמֵר: הָאָדָם הַזֶּה שֶׁאֲנִי מְשַׁלֶּחֲךָ אֶצְלוֹ, נַדְרָן הוּא, כְּעִנְיָן שֶׁנֶּאֱמַר (תהלים קלב:ב-ג): ״אֲשֶׁר נִשְׁבַּע לַה׳ נָדַר לַאֲבִיר יַעֲקֹב אִם אָבֹא בְּאֹהֶל בֵּיתִי״, שֶׁמָּא יֹאמַר אֵינִי אוֹכֵל וְאֵינִי שׁוֹתֶה עַד שֶׁאֶעֱשֶׂה כָּךְ, וְנִמְצֵאתִי מַפְסִידוֹ (ילקוט שמעוני רמז קמג):",1,0],[7,6,"בְּאֹהֶל וּבְמִשְׁכָּן. מִשְׁכַּן שִׁילֹה לֹא הָיְתָה בּוֹ תִּקְרָה, אֶלָּא בַּיִת שֶׁל אֲבָנִים מִלְּמַטָּן, וִירִיעוֹת מִלְמַעְלָן:",1,0],[7,7,"הֲדָבָר דִּבַּרְתִּי. לְשׁוֹן תְּמִיהָ הוּא, לְכָךְ הוּא נָקוּד ה״א חֲטַף פַּתַּ״ח, וְהַדָּלֶ״ת רָפֵי:",1,0],[7,8,"מִן הַנָּוֶה. דִּיר הָרוֹעִים, כְּמוֹ (צפניה ב:ו): ״נְוֹת כְּרוֹת רוֹעִים״:",1,0],[7,9,"כְּשֵׁם הַגְּדוֹלִים. זֶהוּ שֶׁאוֹמְרִים מָגֵן דָּוִד:",1,0],[7,9,"וָאַכְרִיתָה אֶת כָּל אֹיְבֶיךָ. וּלְכָךְ עָלָה עַל לִבְּךָ לִבְנוֹת הַבַּיִת, כְּמָה שֶׁכָּתוּב בַּתּוֹרָה:",2,0],[7,10,"וְשַׂמְתִּי מָקוֹם. עוֹד אֲנִי חָפֵץ לְהַשְׁקִיט, שֶׁיְּהֵא שָׁקֵט וְשָׁלֵו אֶת עַמִּי בִּימֵי בְּנֶךָ:",1,0],[7,11,"וּלְמִן הַיּוֹם אֲשֶׁר צִוִּיתִי. מְחֻבָּר עַל הָעֶלְיוֹן, וְלֹא יוֹסִיפוּ לְעַנּוֹתוֹ כַּאֲשֶׁר בָּרִאשׁוֹנָה קֹדֶם הַשּׁוֹפְטִים, וְכַאֲשֶׁר עָשׂוּ מִימֵי הַשּׁוֹפְטִים עַד כָּאן:",1,0],[7,11,"וַהֲנִיחֹתִי לְךָ. יוֹתֵר וְיוֹתֵר, עַד שֶׁתָּנוּחַ מִכָּל אוֹיְבֶיךָ:",2,0],[7,11,"וְהִגִּיד לְךָ ה׳. הַיּוֹם עַל יָדִי, כִּי בַיִת יַעֲשֶׂה לְּךָ לְהוֹשִׁיב בִּנְךָ עַל כִּסְאֲךָ, וְיִתְקַיֵּם לְךָ בֵּית הַמַּלְכוּת, וְהוּא יִבְנֶה הַבַּיִת:",3,0],[7,14,"בְּשֵׁבֶט אֲנָשִׁים. זֶה הֲדַד וְרָזוֹן בֶּן אֶלְיָדָע:",1,0],[7,14,"וּבְנִגְעֵי בְּנֵי אָדָם. זֶה אַשְׁמְדַאי, שֶׁדָּחָהוּ מִמַּלְכוּתוֹ, וְהַשֵּׁדִים בְּנֵי אָדָם הָרִאשׁוֹן הֵם, שֶׁכָּל מֵאָה וּשְׁלֹשִׁים שָׁנָה שֶׁפֵּרַשׁ אָדָם מֵאִשְׁתּוֹ בְּמוֹת הֶבֶל, הָיוּ הָרוּחוֹת מִתְיַחֲמוֹת וְיוֹלְדוֹת הֵימֶנּוּ (ילקוט שמעוני רמז קמו):",2,0],[7,18,"וַיֵּשֶׁב לִפְנֵי ה׳. לִפְנֵי הָאָרוֹן:",1,0],[7,18,"עַד הֲלֹם. שֶׁהִמְלַכְתַּנִי:",2,0],[7,19,"גַּם אֶל בֵּית עַבְדְּךָ. לְהַמְלִיךְ אֶת בְּנִי אַחֲרַי:",1,0],[7,19,"וְזֹאת תּוֹרַת הָאָדָם. בִּתְמִיהָ, רָאוּי לְהִתְבַּשֵּׂר כֵּן לְבָשָׂר וָדָם. דָּבָר אַחֵר: עָשִׂיתָ לִי כְּמוֹ שֶׁעָשִׂיתָ לְאָדָם הָרִאשׁוֹן, שֶׁהֶרְאֵיתָ לוֹ דּוֹרוֹת הָעֲתִידִים לָצֵאת מִמֶּנּוּ:",2,0],[7,20,"וּמַה יּוֹסִיף דָּוִד עוֹד לְדַבֵּר אֵלֶיךָ. מַה אֶשְׁאַל עוֹד:",1,0],[7,20,"אַתָּה יָדַעְתָּ אֶת עַבְדְּךָ. נָתַתָּ לִי כָּל צְרָכַי, כְּמוֹ (משלי יב:י): ״יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ״:",2,0],[7,21,"בַּעֲבוּר דְּבָרְךָ. לְהָקִים מַה שֶּׁאָמַרְתָּ לִשְׁמוּאֵל, לְהַמְלִיכֵנִי:",1,0],[7,21,"וּכְלִבְּךָ. רְצוֹנְךָ הוּא, וְלֹא שֶׁאֲנִי כְּדַאי:",2,0],[7,21,"לְהוֹדִיעַ אֶת עַבְדֶּךָ. הַבְּשׂוֹרָה שֶׁבִּשַּׂרְתַּנִי:",3,0],[7,23,"אֲשֶׁר הָלְכוּ אֱלֹהִים. מֹשֶׁה וְאַהֲרֹן, שֶׁנֶּאֱמַר (שמות ז:א): ״נְתַתִּיךָ אֱלֹהִים לְפַרְעֹה״, וְכֵן תִּרְגֵּם יוֹנָתָן: ״דְּאָזְלוּ שְׁלוּחִין מִן קֳדָם ה׳״:",1,0],[7,23,"לִפְדּוֹת לוֹ לְעָם. כָּךְ אָמְרוּ הַשְּׁלוּחִים לְיִשְׂרָאֵל: הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלָחָנוּ לִפְדּוֹת לוֹ לְעָם, וְלָשׂוּם לוֹ שֵׁם, וְלַעֲשׂוֹת לָכֶם הַגְּדֻלָּה:",2,0],[7,23,"וְנוֹרָאוֹת. עָשִׂיתָ לְאַרְצְךָ לְאַחַר שֶׁיָּצְאוּ מִשָּׁם, וּמָה הֵם הַנּוֹרָאוֹת, מִפְּנֵי עַמְּךָ, לְגָרֵשׁ עַמִּים וֵאלֹהֵיהֶם, וּמִקְרָא זֶה חָסֵר ׳לְגָרֵשׁ׳, וּבְדִבְרֵי הַיָּמִים (דברי הימים א יז:כא) פֵּרְשׁוֹ: ״לְגָרֵשׁ מִפְּנֵי עַמְּךָ אֲשֶׁר פָּדִיתָ מִמִּצְרַיִם גּוֹיִם וֵאלֹהָיו״, וְאֵינוֹ חִסָּרוֹן, כִּי מִמַּשְׁמָע שֶׁנֶּאֱמַר מִפְּנֵי עַמְּךָ גּוֹיִם, אָנוּ שׁוֹמְעִין לְשׁוֹן טְרוּדִין וְגֵרוּשִׁין:",3,0],[7,28,"אַתָּה הוּא הָאֱלֹהִים. שַׁלִּיט, וְיֵשׁ בְּיָדְךָ יְכֹלֶת לְקַיֵּם:",1,0],[7,29,"הוֹאֵל. רְצֵה:",1,0],[8,1,"מֶתֶג הָאַמָּה. וּבְדִבְרֵי הַיָּמִים (דברי הימים א יח:א) כְּתִיב: ״וַיִּקַּח דָּוִד אֶת גַּת מִיַּד פְּלִשְׁתִּים״, וְהִיא נִקְרֵאת מֶתֶג הָאַמָּה, עַל שֵׁם שֶׁהוּא מַקֵּל רוֹדֶה בְּכָל הַפְּלִשְׁתִּים, מֶטְרוֹפּוֹלִין שֶׁל מְלָכִים, שֶׁלֹּא מָצִינוּ בְּכָל סַרְנֵי פְּלִשְׁתִּים בְּעַזָּה וּבְאַשְׁדּוֹד וּבְעֶקְרוֹן וּבְאַשְׁקְלוֹן שֵׁם מַלְכוּת, אֶלָּא בְגַת מָצִינוּ, (שמואל א כא:יא): ״אָכִישׁ מֶלֶךְ גַּת״:",1,0],[8,1,"מֶתֶג. אגויילו״ן בְּלַעַ״ז:",2,0],[8,1,"הָאַמָּה. הוּא הַמַּרְדֵּעַ שֶׁל עֵץ:",3,0],[8,2,"וַיְמַדֵּד שְׁנֵי חֲבָלִים לְהָמִית. לְפִי שֶׁהָרְגוּ אֶת אָבִיו וְאֶת אִמּוֹ וְאֶחָיו, שֶׁנֶּאֱמַר (שמואל א כב:ד): ״וַיַּנְחֵם אֶת פְּנֵי מֶלֶךְ מוֹאָב״, וְלֹא מָצִינוּ שֶׁיָּצְאוּ מִשָּׁם:",1,0],[8,3,"בְּלֶכְתּוֹ. כְּשֶׁהָלַךְ הֲדַדְעֶזֶר:",1,0],[8,3,"לְהָשִׁיב יָדוֹ. כְּתַרְגּוּמוֹ: ״לְאַשְׁנָאָה תְחוּמֵיהּ״, שֶׁכָּבַשׁ מִן הָאָרֶץ חוּץ לִגְבוּל אַרְצוֹ, וְהִרְחִיב אֶת גְּבוּלוֹ:",2,0],[8,4,"וַיְעַקֵּר דָּוִד אֶת כָּל הָרֶכֶב. מִשּׁוּם (דברים יז:טז): ״לֹא יַרְבֶּה לּוֹ סוּסִים״:",1,0],[8,4,"וַיּוֹתֵר מִמֶּנּוּ מֵאָה רֶכֶב. שֶׁהָיוּ צְרִיכִין לוֹ לִכְדֵי מֶרְכַּבְתּוֹ, וְהָרֶכֶב אַרְבָּעָה סוּסִים, כְּמוֹ שֶׁנֶּאֱמַר (דברי הימים ב א:יז): ״מֶרְכָּבָה בְּשֵׁשׁ מֵאוֹת כֶּסֶף וְסוּס בַּחֲמִשִּׁים וּמֵאָה״, כָּאן לָמַדְנוּ שֶׁהָרֶכֶב אַרְבָּעָה סוּסִים:",2,0],[8,7,"שִׁלְטֵי הַזָּהָב. הֵם אַשְׁפָּתוֹת שֶׁנּוֹתְנִים בָּהֶם הַחִצִּים, כְּמָה דְאַתְּ אָמֵר (ירמיהו נא:יא): ״הָבֵרוּ הַחִצִּים מִלְאוּ הַשְּׁלָטִים״. כָּל הַפָּרָשִׁיּוֹת הַלָּלוּ סְמָכָן אֵצֶל פָּרָשָׁה שֶׁל בֵּית הַמִּקְדָּשׁ, לְפִי שֶׁמִּכָּל הַמִּלְחָמוֹת הַלָּלוּ, קִבֵּץ הֶקְדֵּשׁוֹת לְצָרְכֵי הַבַּיִת:",1,0],[8,13,"וַיַּעַשׂ דָּוִד שֵׁם. שֶׁקָּבַר אֶת הַהֲרוּגִים שֶׁהָרַג בֶּאֱדוֹם, וְהוּא שֵׁם טוֹב לְיִשְׂרָאֵל, שֶׁקּוֹבְרִין אֶת אוֹיְבֵיהֶם, וְכֵן הוּא אוֹמֵר בְּמִלְחֶמֶת גּוֹג וּמָגוֹג (יחזקאל לט:יג): ״וְקָבְרוּ כָּל עַם הָאָרֶץ וְהָיָה לָהֶם לְשֵׁם״. וּמִנַּיִן שֶׁקְּבָרָן דָּוִד, שֶׁנֶּאֱמַר בְּסֵפֶר מְלָכִים (מלכים א יא:טו): ״וַיְהִי בִּהְיוֹת דָּוִד אֶת אֱדוֹם בַּעֲלוֹת יוֹאָב שַׂר הַצָּבָא לְקַבֵּר אֶת הַחֲלָלִים״:",1,0],[8,13,"שְׁמוֹנָה עָשָׂר אָלֶף. וּבְסֵפֶר תְּהִלִּים (תהלים ס:ב) הוּא אוֹמֵר: ״שְׁנֵים עָשָׂר אָלֶף״, אֱמוֹר מֵעַתָּה, שְׁתֵּי מִלְחָמוֹת הָיוּ:",2,0],[8,14,"נְצִיבִים. פְּקִידִים לִגְבּוֹת מַס:",1,0],[8,15,"וַיְהִי דָוִד עֹשֶׂה מִשְׁפָּט וְגוֹ׳ וְיוֹאָב עַל הַצָּבָא. דָּוִד גָּרַם לְיוֹאָב לִהְיוֹת מַצְלִיחַ עַל הַצָּבָא, לְפִי שֶׁעָשָׂה מִשְׁפָּט וּצְדָקָה, וְיוֹאָב גָּרַם לְדָוִד לַעֲשׂוֹת מִשְׁפָּט וּצְדָקָה, לְפִי שֶׁהוּא דָּן, וְיוֹאָב שׁוֹטֵר וְרוֹדֶה עַל יָדוֹ, וְעוֹד, מִתּוֹךְ שֶׁיּוֹאָב עָסַק בְּמִלְחָמוֹת, לֹא הָיָה דָוִד טָרוּד בָּהֶן, וְלִבּוֹ פָּתוּחַ לִשְׁפּוֹט צֶדֶק:",1,0],[8,16,"מַזְכִּיר. מַזְכִּיר אֵיזֶה דִּין בָּא לְפָנָיו רִאשׁוֹן, לְפָסְקוֹ רִאשׁוֹן:",1,0],[8,18,"וּבְנָיָהוּ בֶן יְהוֹיָדָע וְהַכְּרֵתִי וְהַפְּלֵתִי. תִּרְגֵּם יוֹנָתָן: ״וּבְנָיָהוּ בַּר יְהוֹיָדָע מְמַנָּא עַל קַשָּׁתַיָּא וְעַל קַלָּעַיָּא״. וְרַבּוֹתֵינוּ אָמְרוּ (ברכות ד א) כְּרֵתִי וּפְלֵתִי, אוּרִים וְתֻמִּים:",1,0],[8,18,"כֹּהֲנִים הָיוּ. תִּרְגֵּם יוֹנָתָן: ״רַבְרְבִין הֲווֹ״:",2,0],[9,9,"נָתַתִּי לְבֶן אֲדֹנֶיךָ. הַמֶּלֶךְ רַשַּׁאי לְהַעֲבִיר נַחֲלָה, שֶׁנֶּאֱמַר בְּמִשְׁפַּט הַמְּלוּכָה (שמואל א ח:יד): ״וְאֶת שְׂדוֹתֵיכֶם וְאֶת כַּרְמֵיכֶם וְגוֹ׳ יִקַּח וְנָתַן לַעֲבָדָיו״:",1,0],[9,11,"כֵּן יַעֲשֶׂה עַבְדֶּךָ וּמְפִיבֹשֶׁת אֹכֵל עַל שֻׁלְחָנִי. צִיבָא אָמַר: כֵּן יַעֲשֶׂה עַבְדֶּךָ, וְדָוִד הֵשִׁיב: וּמְפִיבֹשֶׁת אֹכֵל עַל שֻׁלְחָנִי:",1,0],[9,12,"מוֹשַׁב בֵּית צִיבָא. בָּנָיו וַעֲבָדָיו:",1,0],[10,2,"כַּאֲשֶׁר עָשָׂה אָבִיו עִמָּדִי חֶסֶד. וּמַהוּ הַחֶסֶד, כְּשֶׁהָיָה דָוִד בּוֹרֵחַ מִפְּנֵי שָׁאוּל, בָּאוּ אֵלָיו אָבִיו וְאִמּוֹ וְאֶחָיו (שמואל א כב:ד): ״וַיַּנְחֵם אֶת פְּנֵי מֶלֶךְ מוֹאָב״, וַיֹּאמֶר לוֹ יֵשֶׁב נָא אָבִי וְאִמִּי עִמָּךְ, וַהֲרָגָם, חוּץ מֵאֶחָד מֵהֶם שֶׁבָּרַח וְנִמְלַט לְאֶרֶץ בְּנֵי עַמּוֹן אֵצֶל נָחָשׁ, (במדרש רבי תנחומא בוירא אליו):",1,0],[10,3,"הַמְכַבֵּד דָּוִד אֶת אָבִיךָ בְּעֵינֶיךָ. הַנִּרְאֶה בְּעֵינֶיךָ שֶׁדָּוִד מְכַבֵּד אֶת אָבִיךָ, הֵם מֻזְהָרִים לֹא תִדְרֹשׁ שְׁלוֹמָם, וְהוּא יִדְרֹשׁ שְׁלוֹמְךָ:",1,0],[10,4,"מַדְוֵיהֶם. חֲלוּקֵיהֶם:",1,0],[10,4,"שְׁתוֹתֵיהֶם. הָעֲגָבוֹת:",2,0],[10,16,"וְשׁוֹבַךְ שַׂר צְבָא הֲדַדְעֶזֶר. עַל שֵׁם שֶׁהָיָה גִבּוֹר וְעָרִיץ מְאֹד הִזְכִּירוֹ בִּשְׁמוֹ:",1,0],[11,1,"לְעֵת צֵאת הַמְּלָאכִים. יֵשׁ עֵת בַּשָּׁנָה שֶׁדֶּרֶךְ הַחַיָּלוֹת לָצֵאת, כְּשֶׁהָאָרֶץ מְלֵאָה קָמוֹת, וְהַסּוּסִים מוֹצְאִים תְּבוּאָה בַּשָּׂדֶה לֶאֱכוֹל:",1,0],[11,4,"מִטֻּמְאָתָהּ. מִנִּדָּתָהּ:",1,0],[11,6,"שְׁלַח אֵלַי אֶת אוּרִיָּה. שֶׁהָיָה מִתְכַּוֵּין שֶׁיִּשְׁכַּב עִם אִשְׁתּוֹ, וִיהֵא סָבוּר שֶׁמִּמֶּנּוּ הִיא מְעֻבֶּרֶת:",1,0],[11,8,"מַשְׂאַת הַמֶּלֶךְ. (תרגום:) ״סְעוּדְתָּא דְּמַלְכָּא״:",1,0],[11,15,"וְנִכָּה וָמֵת. כְּדֵי שֶׁתְּהֵא מְגֹרֶשֶׁת לְמַפְרֵעַ, וְנִמְצָא שֶׁלֹּא בָּא עַל אֵשֶׁת אִישׁ, שֶׁכָּל הַיּוֹצֵא לַמִּלְחָמָה, כּוֹתֵב גֵּט לְאִשְׁתּוֹ עַל תְּנַאי, אִם יָמוּת בַּמִּלְחָמָה (שבת נו א):",1,0],[11,21,"בֶּן יְרֻבֶּשֶׁת. הוּא גִּדְעוֹן, שֶׁעָשָׂה מְרִיבָה עִם הַבֹּשֶׁת, הוּא הַבַּעַל:",1,0],[11,25,"הַחֲזֵק מִלְחַמְתְּךָ אֶל הָעִיר וְהָרְסָהּ. עַד כָּאן דִּבְרֵי הַשְּׁלִיחוּת:",1,0],[11,25,"וְחַזְּקֵהוּ. דָּוִד אָמַר לַמַּלְאָךְ, וְחַזְּקֵהוּ לְיוֹאָב בְּדִבְרֵי תַנְחוּמִין, שֶׁלֹּא יֵרַךְ לִבּוֹ:",2,0],[12,4,"וַיָּבֹא הֵלֶךְ. דִּמָּה אֶת יֵצֶר הָרָע תְּחִלָּה לְהֵלֶךְ, שֶׁעוֹבֵר לְדַרְכּוֹ, וְאַחַר כָּךְ לְאוֹרֵחַ, שֶׁנַּעֲשָׂה אַכְסְנַאי, וְאַחַר כָּךְ לְאִישׁ, שֶׁהוּא בַּעַל הַבַּיִת:",1,0],[12,5,"כִּי בֶן מָוֶת. הַגּוֹזֵל אֶת הֶעָנִי, כְּאִלּוּ נוֹטֵל אֶת נַפְשׁוֹ, שֶׁנֶּאֱמַר (משלי א:יט): ״אֶת נֶפֶשׁ בְּעָלָיו יִקָּח״:",1,0],[12,6,"יְשַׁלֵּם אַרְבַּעְתָּיִם. כָּךְ אֵרַע לוֹ, שֶׁלָּקָה בְּאַרְבָּעָה בָּנִים, הַיֶּלֶד וְאַמְנוֹן תָּמָר וְאַבְשָׁלוֹם:",1,0],[12,8,"וְאֶת נְשֵׁי אֲדֹנֶיךָ. מִיכַל בַּת שָׁאוּל:",1,0],[12,8,"וְאֹסִפָה. וְהָיִיתִי מוֹסִיף לְךָ:",2,0],[12,14,"כִּי נִאֵץ נִאַצְתָּ אֶת אוֹיְבֵי. כִּנּוּי הוּא זֶה, דֶּרֶךְ כָּבוֹד לְמַעְלָה וְיוֹנָתָן תִּרְגֵּם: ״אֲרֵי מֵיפְתַּח פְּתַחְתָּא פּוּמָא דְּסָנְאֵי עַמָּא דַה׳״:",1,0],[12,15,"וַיֵּאָנַשׁ. לְשׁוֹן חֹלִי:",1,0],[12,16,"וּבָא וְלָן וְשָׁכַב אָרְצָה. וּבָא הַבַּית, וְלָן בַּלַּיְלָה שׁוֹכֵב לָאָרֶץ:",1,0],[12,17,"וְלֹא בָרָה. לְשׁוֹן אֲכִילָה, כְּמוֹ (שמואל ב יג:ו): ״וְאֶבְרֶה מִיָּדָהּ״:",1,0],[12,25,"בַּעֲבוּר ה׳. אֲשֶׁר אֲהֵבוֹ:",1,0],[12,26,"אֶת עִיר הַמְּלוּכָה. שְׁנֵי חִזּוּקֵי חוֹמָה הָיוּ בָּהּ, חִיצוֹנָה וּפְנִימִית, עִיר הַחִיצוֹנָה, עִיר מְלוּכָה, וְהַפְּנִימִית, לְמִבְצָר וּלְחוֹזֶק:",1,0],[12,30,"אֶת עֲטֶרֶת מַלְכָּם. תּוֹעֲבַת בְּנֵי עַמּוֹן ׳מִלְכֹּם׳ שְׁמוֹ, לְשׁוֹן מֹלֶךְ:",1,0],[12,30,"וַתְּהִי עַל רֹאשׁ דָּוִד. אִתַּי הַגִּתִּי בִּטְּלָהּ (עבודה זרה מד א):",2,0],[12,31,"מְגֵרָה וַחֲרִצִים וּמַגְזְרוֹת. כְּמִין פְּצִירָה פִּים שֶׁקּוֹרִין לימ״א, מִינֵי יִסּוּרִים הֵם:",1,0],[12,31,"מְגֵרָה. סַכִּין פָּגוּם פְּגִימוֹת הַרְבֵּה תְּכוּפוֹת זוֹ לָזוֹ:",2,0],[12,31,"חֲרִצִים. הוּא מוֹרַג חָרוּץ מָלֵא חֲרִיצִים, כְּמִין פְּצִירָה פִּים שֶׁקּוֹרִין לימ״א:",3,0],[12,31,"בַּמַּלְבֵּן. בְּטִיט חוּצוֹת, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וּגְרַר יָתְהוֹן בְּשׁוּקַיָּא״:",4,0],[13,1,"וּלְאַבְשָׁלוֹם אָחוֹת יָפָה. שֶׁהָיְתָה בַּת אִמּוֹ:",1,0],[13,2,"לְהִתְחַלּוֹת. עַד שֶׁנֶּחֱלָה:",1,0],[13,2,"כִּי בְתוּלָה הִיא. צְנוּעָה בַּבַּיִת וְאֵינָהּ יוֹצֵאת לַחוּץ, לְפִיכָךְ וַיִּפָּלֵא בְּעֵינֵי אַמְנוֹן וְגוֹ׳, נִכְסֶה וְנֶעְלָם מִמֶּנּוּ מָה תּוֹאֲנָה יָכוֹל לְבַקֵּשׁ וְיִשְׁכַּב עִמָּהּ, כְּמוֹ (דברים יז:ח): ,כִּי יִפָּלֵא מִמְּךָ״, ״אֲרֵי יִתְכַּסֵּי מִמָּךְ״:",2,0],[13,3,"אִישׁ חָכָם. לְרִשְׁעָה:",1,0],[13,4,"דַּל. כָּחוּשׁ, כְּמוֹ (בראשית מא:יט): ״דַּלּוֹת וְרָעוֹת תֹּאַר״:",1,0],[13,5,"אֶת הַבִּרְיָה. אֶת הַסְּעוּדָה:",1,0],[13,8,"וַתְּלַבֵּב. וַתַּחֲלוֹט, סֹלֶת מֻרְבֶּכֶת בְּמַיִם רוֹתְחִין תְּחִלָּה, וְאַחַר כָּךְ בְּשֶׁמֶן:",1,0],[13,9,"אֶת הַמַּשְׂרֵת. תַּרְגּוּם שֶׁל מַחֲבַת, מַסְרֵיתָא:",1,0],[13,13,"כִּי לֹא יִמְנָעֵנִי מִמֶּךָּ. שֶׁמֻּתֶּרֶת אֲנִי לְךָ, לְפִי שֶׁנִּתְעַבְּרָה בִּי אִמִּי כְּשֶׁהִיא נָכְרִית יְפַת תֹּאַר, שֶׁלְּקָחָהּ דָּוִד בַּמִּלְחָמָה, וּמִי שֶׁיֵּשׁ לוֹ בֵּן אוֹ בַּת מִן שִׁפְחָה, אֵינוֹ בְּנוֹ לְכָל דָּבָר:",1,0],[13,15,"וַיִּשְׂנָאֶהָ אַמְנוֹן. אָמְרוּ רַבּוֹתֵינוּ (סנהדרין כא א): נִימָא נִקְשְׁרָה לוֹ, וַעֲשָׂאַתוּ כְּרוּת שָׁפְכָה:",1,0],[13,16,"אַל אוֹדוֹת. אַל תַּעֲשֶׂה אוֹדוֹת הָרָעָה הַזֹּאת שֶׁל שִׁלּוּחַ, הַגְּדוֹלָה מִן הָאַחֶרֶת שֶׁעָשִׂיתָ עִמִּי וְעִנִּיתָנִי, וְעוֹד תּוֹסִיף רָעָה מִמֶּנָּה לְשַׁלְּחֵנִי:",1,0],[13,23,"וַיִּהְיוּ גוֹזְזִים. וְדַרְכָּם הָיָה לַעֲשׂוֹת מִשְׁתֶּה בִּגְזוֹז צֹאנָם:",1,0],[13,26,"וְלֹא יֵלֶךְ נָא אִתָּנוּ. וְאִם לֹא יָכוֹל אַתָּה לָלֶכֶת, יֵלֶךְ נָא עִמָּנוּ אַמְנוֹן:",1,0],[13,32,"עַל פִּי אַבְשָׁלוֹם הָיְתָה שׂוּמָה. בְּצִוּוּיוֹ שֶׁל אַבְשָׁלוֹם הָיְתָה שִׂימָה זוֹ נִשֹּׁמֶת עַל עֲבָדָיו, לַהֲרוֹג אֶת אַמְנוֹן:",1,0],[13,39,"וַתְּכַל דָּוִד. הֲרֵי זֶה מִקְרָא קָצָר, וַתְּכַל נֶפֶשׁ דָּוִד; וְכֵן תִּרְגֵּם יוֹנָתָן: ״וְחֲמִידַת נַפְשָׁא דְדָוִד״, כְּמוֹ (תהלים פד:ג): ״נִכְסְפָה וְגַם כָּלְתָה״, לְשׁוֹן תַּאֲוָה:",1,0],[13,39,"כִּי נִחַם עַל אַמְנוֹן. קִבֵּל תַּנְחוּמִין:",2,0],[14,2,"וַיִּשְׁלַח יוֹאָב תְּקוֹעָה. אָמְרוּ רַבּוֹתֵינוּ (מנחות פה ב): כִּי שֶׁמֶן זַיִת מָצוּי שָׁם, לְכָךְ חָכְמָה מְצוּיָה שָׁם:",1,0],[14,5,"אֲבָל אִשָּׁה אַלְמָנָה אָנִי. אֲבָל, ״בְּקוּשְׁטָא״:",1,0],[14,9,"עָלַי אֲדֹנִי הַמֶּלֶךְ הֶעָוֹן. כִּנּוּי הוּא לִכְבוֹדוֹ, כְּלוֹמַר אַתָּה מַדְחֶה אוֹתִי לֵאמֹר אֲנִי מְצַוֶּה עָלֶיךָ וַאֲנִי אֵלֵךְ לְדַרְכִּי, וְאַתָּה לֹא תְצַוֶּה עָלַי, וּבְנִי יֵהָרֵג, עַל מִי הֶעָוֹן הַזֶּה:",1,0],[14,11,"יִזְכָּר נָא הַמֶּלֶךְ אֶת ה׳. שֶׁהִקְפִּיד עַל אֹרֶךְ הַדֶּרֶךְ לְהַצִּיל נְפָשׁוֹת, שֶׁנֶּאֱמַר (דברים יט:ו): ״וְהִשִּׂיגוֹ כִּי יִרְבֶּה הַדֶּרֶךְ״, וְזֶהוּ מֵהַרְבּוֹת גֹּאֵל הַדָּם לְשַׁחֵת, וְאַתָּה דוֹחֶה אוֹתִי:",1,0],[14,13,"וְלָמָּה חָשַׁבְתָּה כָזֹאת. שֶׁחָשַׁדְתָּ לְיִשְׂרָאֵל, שֶׁיָּבֹאוּ לַהֲרוֹג אֶת הַשֵּׁנִי בְּלֹא עֵדִים וְהַתְרָאָה:",1,0],[14,13,"וּמִדַּבֵּר הַמֶּלֶךְ הַדָּבָר הַזֶּה כְּאָשֵׁם. וְהַדָּבָר הַזֶּה שֶׁחָרַצְתָּ לַאֲחֵרִים, שֶׁאָמַרְתָּ לִי לֹא יִפּוֹל מִשַּׂעֲרַת בְּנֵךְ אַרְצָה, עַכְשָׁיו שֶׁאֲגַלֶּה לְךָ שֶׁאֵין הַדָּבָר הַזֶּה אֶלָּא עַל שְׁנֵי בָּנֶיךָ, אַל תִּתְחָרֵט לֵאמֹר דִּבַּרְתִּי זֶה כְּאָשֵׁם, וְהִנְנִי חוֹזֵר בִּי, לְבִלְתִּי הָשִׁיב הַמֶּלֶךְ אֶת אַבְשָׁלוֹם בְּנוֹ שֶׁנִּדְחָה מִמֶּנּוּ וּבָרַח לוֹ:",2,0],[14,13,"וּמִדַּבֵּר הַמֶּלֶךְ. אוקינו״ן פרלטי״ש בלע״ז:",3,0],[14,14,"כִּי מוֹת נָמוּת. וְדַיֵּינוּ בְּאוֹתוֹ עֹנֶשׁ:",1,0],[14,14,"וְלֹא יִשָּׂא אֱלֹהִים נֶפֶשׁ. אִישׁ מִן הַמִּיתָה, לְפִיכָךְ וְחָשַׁב הַמֶּלֶךְ מַחֲשָׁבוֹת לְבִלְתִּי יִדַּח מִמֶּנּוּ נִדָּח:",2,0],[14,15,"וְעַתָּה אֲשֶׁר בָּאתִי לְדַבֵּר אֶל הַמֶּלֶךְ אֲדֹנִי אֶת הַדָּבָר הַזֶּה. בְּכִנּוּי עָלַי וְעַל בְּנִי:",1,0],[14,15,"כִּי יֵרְאוּנִי הָעָם. הִפְחִידוּנִי מִלְּבַקֵּשׁ אֶת אֲדֹנִי עַל בְּנוֹ, פֶּן יִכְעוֹס עָלַי:",2,0],[14,15,"וַתֹּאמֶר שִׁפְחָתְךָ אֲדַבְּרָה נָּא. כְּעִנְיָן זֶה, אוּלַי יַעֲשֶׂה וְגוֹ׳:",3,0],[14,16,"כִּי יִשְׁמַע הַמֶּלֶךְ לְהַצִּיל אֶת אֲמָתוֹ מִכַּף הָאִישׁ. הַבָּא לַהֲרוֹג אֶת בְּנִי, וּלְהַשְׁמִידֵנוּ יַחַד מִנַּחֲלַת אֱלֹהִים:",1,0],[14,17,"וַתֹּאמֶר שִׁפְחָתְךָ. מֵאַחַר שֶׁיְּצַוֶּה הַמֶּלֶךְ עָלַי, יִהְיֶה דְּבָרוֹ לִמְנוּחָה לִבְנִי, כִּי לֹא יָשׁוּב מִדְּבָרוֹ הַטּוֹב, כִּי כְּמַלְאַךְ ה׳ אֲדֹנִי הַמֶּלֶךְ, וְלֹא יַחֲזִירֶנּוּ כַּעַס וְשִׂנְאָה מִדְּבָרוֹ הַטּוֹב:",1,0],[14,19,"אִם אִשׁ. כְּמוֹ אִם יֵשׁ, כְּמוֹ הֲיֵשׁ, וְכֵן (מיכה ו:י): ״עוֹד הָאִשׁ בֵּית רָשָׁע״, כְּמוֹ הֲיֵשׁ:",1,0],[14,20,"לְבַעֲבוּר סַבֵּב. לְגַלְגֵּל, עַד שֶׁיֵּצֵא דְּבַר בְּנוֹ שֶׁל הַמֶּלֶךְ לָאוֹר:",1,0],[14,20,"וַאדֹנִי חָכָם. וְהֵבַנְתָּ כִּי מֵאֵת יוֹאָב יָצָאתָ:",2,0],[14,30,"אֶל יָדִי. סָמוּךְ לִרְשׁוּתִי, בְּמָקוֹם שֶׁאֲנִי יָכוֹל לְהַזִּיק:",1,0],[14,30,"אֶל יָדִי. אינמי״ש אוש״ט בלע״ז:",2,0],[14,32,"וֶהֱמִתָנִי. וְיַהֲרֹג אוֹתִי הַמֶּלֶךְ:",1,0],[15,1,"וַחֲמִשִּׁים אִישׁ וגו׳. כֻּלָּם נְטוּלֵי טְחוֹל, וַחֲקוּקֵי כַּפּוֹת רַגְלַיִם:",1,0],[15,2,"וְהִשְׁכִּים אַבְשָׁלוֹם. בְּכָל בֹּקֶר:",1,0],[15,2,"מֵאַחַד שִׁבְטֵי יִשְׂרָאֵל עַבְדֶּךָ. מִשֵּׁבֶט פְּלוֹנִי:",2,0],[15,4,"וְהִצְדַּקְתִּיו. (תרגום:) ״וַאֲדִינְנֵיהּ בְּקוּשְׁטָא״:",1,0],[15,7,"מִקֵּץ אַרְבָּעִים שָׁנָה. שֶׁשָּׁאֲלוּ יִשְׂרָאֵל מֶלֶךְ מִשְּׁמוּאֵל, נִתְגַּלְגֵּל דְּבַר מֶרֶד וְהַשְׁפָּלָה בַּמַּלְכוּת:",1,0],[15,7,"אֵלְכָה נָּא. לְחֶבְרוֹן:",2,0],[15,7,"וַאֲשַׁלֵּם אֶת נִדְרִי. אָמְרוּ רַבּוֹתֵינוּ (סוטה לד ב): לְהָבִיא כְּבָשִׂים מֵחֶבְרוֹן, כִּי שָׁם הָיוּ כְּבָשִׂים שְׁמֵנִים:",3,0],[15,11,"קְרֻאִים וְהֹלְכִים לְתֻמָּם. מְפֹרָשׁ בְּמַסֶּכֶת סוֹטָה יְרוּשַׁלְמִית (א ח) שֶׁבִּקֵּשׁ מֵאָבִיו שֶׁיִּכְתֹּב לוֹ, שֶׁכָּל שְׁנֵי בְּנֵי אָדָם שֶׁיְּבַקֵּשׁ שֶׁיֵּלְכוּ עִמּוֹ, יֵלְכוּ וְהָיָה מַרְאֶה אוֹתוֹ לִשְׁנַיִם כָּאן, וְאַחַר כָּךְ לִשְׁנַיִם אֲחֵרִים, וְכֵן הַרְבֵּה:",1,0],[15,17,"בֵּית הַמֶּרְחָק. (תרגום:) ״בַּאֲתַר דְּרָחִיק״:",1,0],[15,18,"עַל יָדוֹ. אֶצְלוֹ, הוּא עוֹמֵד וְהֵם עוֹבְרִים:",1,0],[15,19,"עִם הַמֶּלֶךְ. עִם אַבְשָׁלוֹם:",1,0],[15,19,"כִּי נָכְרִי אַתָּה. וַאֲנַחְנוּ בּוֹרְחִים מֵאֵין צֵידָה וּמָזוֹן, וּמִתּוֹךְ שֶׁאַתָּה נָכְרִי לֹא תִּמְצָא מְרַחֲמִים:",2,0],[15,19,"וְגַם גּוֹלֶה אַתָּה לִמְקוֹמֶךָ. וְגַם אִם גּוֹלֶה אַתָּה מֵעִם הַמֶּלֶךְ שֶׁאֵינְךָ רוֹצֶה לִהְיוֹת עִמּוֹ, לִמְקוֹמְךָ חֲזוֹר לְךָ, כִּי לֹא טוֹב לֶכְתְּךָ עִמִּי, שֶׁהֲרֵי תְּמוֹל בָּאתָ:",3,0],[15,20,"וְהַיּוֹם אֲנִיעֲךָ עִמָּנוּ. וְאֵין לִי מָקוֹם שֶׁאוּכַל לְהוֹשִׁיבְךָ שָׁם וּלְהִמָּלֵט, כִּי אֲנִי הוֹלֵךְ אֶל אֲשֶׁר יִקְרֵנִי הַמִּקְרֶה לָלֶכֶת, יוֹם יוֹם כְּשֶׁאֶשְׁמַע שֶׁהָרוֹדְפִים כָּאן, אֲנִי בּוֹרֵחַ כָּאן, וְכֵן תִּרְגֵּם יוֹנָתָן ״וְגַם גּוֹלֶה אַתָּה לִמְקוֹמֶךָ״ (לעיל פסוק יט): ״וְאַף אִם גְּלֵי אַתְּ אָזֵיל לָךְ לְאַתְרָךְ״:",1,0],[15,20,"חֶסֶד וֶאֱמֶת. אֲנִי מַחֲזִיק בְּךָ טוֹבַת חֶסֶד וֶאֱמֶת שֶׁעָשִׂיתָ עִמָּדִי:",2,0],[15,22,"לֵךְ וַעֲבֹר. עִם שְׁאָר הָעָם, אַחַר אֲשֶׁר אֵינְךָ רוֹצֶה לְהִפָּרֵד מִמֶּנִּי:",1,0],[15,23,"וְכָל הָעָם עֹבְרִים. מִן הַמֶּלֶךְ וָהָלְאָה, לְפִי שֶׁהוּא עוֹמֵד, קוֹרֵא אוֹתָם עוֹבְרִים:",1,0],[15,24,"וַיַּצִּקוּ. כְּמוֹ וַיַּצִּיגוּ, (תרגום:) ״וַאֲקִימוּ יָת אֲרוֹנָא״, הֶעֱמִידוּהוּ לְצַד אֶחָד, וְהָעָם עוֹבְרִים, שֶׁהָיָה דָוִד רוֹצֶה לְשָׂאתוֹ עִמּוֹ:",1,0],[15,24,"וַיַּעַל אֶבְיָתָר עַד תֹּם וגו׳. הֲרֵי זֶה מִקְרָא מְסֹרָס, וַיַּצִּיקוּ אֶת אֲרוֹן הָאֱלֹהִים עַד תֹּם כָּל הָעָם לַעֲבוֹר:",2,0],[15,24,"וַיַּעַל אֶבְיָתָר. אוֹתוֹ הַיּוֹם נִסְתַּלֵּק מִן הַכְּהוּנָּה, שֶׁשָּׁאַל בָּאוּרִים וְתוּמִּים וְלֹא נַעֲנָה, וְנִכְנַס צָדוֹק תַּחְתָּיו, וְכֵן שָׁנִינוּ בְּסֵדֶר עוֹלָם וּבְסֵדֶר יוֹמָא (עג ב):",3,0],[15,27,"הֲרוֹאֶה אַתָּה. אִם רוֹאֶה אַתָּה שֶׁעֵצָה נְכוֹנָה הִיא, שׁוּב הָעִיר וגו׳:",1,0],[15,27,"שְׁנֵי בְנֵיכֶם אִתְּכֶם. בְּיָדָם תּוּכְלוּ לְהוֹדִיעֵנִי מַה שֶּׁתִּשְׁמְעוּ מִבֵּית הַמֶּלֶךְ, לְפִי מַה שֶּׁתּוֹדִיעוּנִי אִמָּלֵט:",2,0],[15,30,"בְּמַעֲלֵה הַזֵּיתִים. בְּהַר הַזֵּיתִים:",1,0],[15,30,"חָפוּי. מְכֹרָךְ, כְּדֶרֶךְ הָאֲבֵלִים:",2,0],[15,30,"חָפוּ. (תרגום:) ״כְּרִיכוּ״:",3,0],[15,31,"וְדָוִד הִגִּיד. וּלְדָוִד הִגִּיד הַמַּגִּיד:",1,0],[15,31,"סַכֶּל. קַלְקֵל, כְּמוֹ (קהלת י:יד): ״הַסָּכָל יַרְבֶּה דְבָרִים״:",2,0],[15,32,"בָּא עַד הָרֹאשׁ. (תרגום:) ״עַד רֵישׁ טוּרְיָא״:",1,0],[15,32,"אֲשֶׁר יִשְׁתַּחֲוֶה שָׁם לֵאלֹהִים. אֲשֶׁר הָיָה רָגִיל לְהִשְׁתַּחֲווֹת שָׁם כְּשֶׁהָיָה בָּא לִירוּשָׁלַיִם, הָיָה רוֹאֶה מִשָּׁם אֶת הָאֹהֶל שֶׁהָאָרוֹן בְּתוֹכוֹ, וְהָיָה מִשְׁתַּחֲוֶה:",2,0],[15,34,"עֶבֶד אָבִיךָ וַאֲנִי מֵאָז. כְּמוֹ וַאֲנִי עֶבֶד אָבִיךָ מֵאָז, וּמִקְרָא מְסֹרָס הוּא:",1,0],[15,37,"יָבוֹא יְרוּשָׁלִָם. נָתַן לִבּוֹ שֶׁיָּבֹא לִירוּשָׁלַיִם:",1,0],[16,1,"וּמֵאָה קַיִץ. (תרגום:) ״וּמְאָה מְנָן דְּבֵילְתָּא״:",1,0],[16,10,"כֹּה יְקַלֵּל. כֵּן יְקַלֵּל:",1,0],[16,10,"ה׳ אָמַר לוֹ. אֶפְשָׁר אָדָם כְּמוֹתוֹ שֶׁהוּא רֹאשׁ לְסַנְהֶדְרִין, יְקַלֵּל אֶת הַמֶּלֶךְ אִם לֹא שֶׁנֶּאֱמַר לוֹ מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[16,12,"יִרְאֶה ה׳ בְּעֵינִי. דִּמְעַת עֵינִי:",1,0],[16,14,"וַיִּנָּפֵשׁ שָׁם. בְּבַחוּרִים:",1,0],[16,21,"וְחָזְקוּ יְדֵי כָּל אֲשֶׁר אִתָּךְ. כִּי עַתָּה יָדָם רָפָה לַעֲזֹר לְךָ, שֶׁאוֹמְרִים בְּלִבָּם הַבֵּן יִתְחָרֵט אֵצֶל אָבִיו, וָאָנוּ נִהְיֶה שְׂנוּאִים לַמֶּלֶךְ:",1,0],[17,3,"כְּשׁוּב הַכֹּל. אֵלֶיךָ:",1,0],[17,3,"הָאִישׁ אֲשֶׁר אַתָּה מְבַקֵּשׁ. יַעֲשֶׂה בּוֹ בַּקָּשָׁתְךָ וְיֵהָרֵג, וְאַחַר כָּךְ כָּל הָעָם יִהְיֶה שָׁלוֹם, וְזֶה מִקְרָא קָצָר:",2,0],[17,4,"וּבְעֵינֵי זִקְנֵי יִשְׂרָאֵל. זִקְנֵי אַשְׁמַאי:",1,0],[17,8,"וְאָבִיךָ אִישׁ מִלְחָמָה. וְיוֹדֵעַ עִנְיְנֵי מִלְחָמָה וְטַכְסִיסֶיהָ וְטִיב מַאֲרָב, וּבָטוּחַ הוּא שֶׁתִּרְדֹּף הַלַּיְלָה לָבֹא עָלָיו, לְפִיכָךְ לֹא יָלִין עִם שְׁאָר הָעָם:",1,0],[17,9,"הִנֵּה עַתָּה הוּא נֶחְבָּא. וּכְשֶׁתָּבֹא עַל מַחֲנֵה הָעָם אֲשֶׁר אִתּוֹ, הוּא לֹא יִהְיֶה שָׁם שֶׁתַּהַרְגֶנּוּ:",1,0],[17,9,"וְהָיָה כִּנְפֹל בָּהֶם בַּתְּחִלָּה. אֲנִי אָמַרְתִּי לְךָ כִּי אֲנָשָׁיו גִּבּוֹרִים וּמָרֵי נֶפֶשׁ, וְאִם יַהַרְגוּ בְּעַמְּךָ, תִּהְיֶה בָּם מַפָּלָה בְּמִלְחָמָה זוֹ שֶׁהִיא רִאשׁוֹנָה, וְשָׁמַע הַשּׁוֹמֵעַ מִכָּל יִשְׂרָאֵל הַבָּאִים לְהִתְחַבֵּר אֵלֶיךָ, וְאָמַר הָיְתָה מַגֵּפָה בָּעָם שֶׁל אַבְשָׁלוֹם:",2,0],[17,10,"וְהוּא גַם בֶּן חַיִל. וְאוֹתוֹ הַשּׁוֹמֵעַ אֲפִלּוּ הוּא בֶּן חַיִל וְלִבּוֹ כְּלֵב הָאַרְיֵה, הִמֵּס יִמַּס בְּפַחַד וּרְעָדָה, וְלֹא יִתְקַשֵּׁר עוֹד אֵלֶיךָ, כִּי יֹאמַר כְּבָר הִתְחִיל לִפּוֹל וְנֶעֱנָשׁ הוּא עַל אָבִיו, וְלֹא יַצְלִיחַ:",1,0],[17,11,"כִּי יָעַצְתִּי. כִּי זֹאת עֲצָתִי:",1,0],[17,11,"וּפָנֶיךָ הוֹלְכִים בַּקְרָב. בָּרֹאשׁ, (תרגום:) ״וְאַתְּ תְּהֵי אָזֵיל בְּרֵישׁ כּוּלָּנָא״:",2,0],[17,12,"וְנַחְנוּ עָלָיו. וְנָנוּחַ עָלָיו, לְשׁוֹן חֲנִיָּה, כְּמוֹ ״וַיָּנַח בְּכָל גְּבוּל מִצְרָיִם״ (שמות י:יד), ״נָחָה אֲרָם עַל אֶפְרָיִם״ (ישעיהו ז:ב):",1,0],[17,13,"חֲבָלִים. (תרגום:) ״מַשִׁרְיָן״, כְּמוֹ ״חֶבֶל נְבִיאִים״ (שמואל א י:ה) ״חֶבְלֵי רְשָׁעִים״ (תהלים קיט:סא):",1,0],[17,13,"עַד הַנַּחַל. חוֹמַת הָעִיר נִסְחוֹב אֶל הַגַּי:",2,0],[17,16,"וְגַם עָבוֹר תַּעֲבֹר. אֶת הַיַּרְדֵּן:",1,0],[17,16,"פֶּן יְבֻלַּע לַמֶּלֶךְ. שֶׁלֹּא יָעַצְתִּיו לְטוֹבָה, וְיַעֲשֶׂה כְּדִבְרֵי אֲחִיתֹפֶל:",2,0],[17,16,"יְבֻלַּע. יֵאָמֵר לוֹ בְּסֵתֶר וּבִבְלִיעָה:",3,0],[17,17,"בְּעֵין רֹגֵל. (תרגום:) ״בְּעֵין קַצָּרָא״, כּוֹבְסֵי בִּגְדֵי צֶמֶר, שֶׁחוֹבְטִין אוֹתָם שָׁם, שֶׁבּוֹעֲטִים אוֹתָם בָּרֶגֶל:",1,0],[17,19,"אֶת הַמָּסָךְ. וִילוֹן:",1,0],[17,19,"הָרִפוֹת. חִטִּין כְּתוּשׁוֹת, כְּמוֹ ״בְּתוֹךְ הָרִיפוֹת״ (משלי כז:כב):",2,0],[17,20,"מִיכַל הַמָּיִם. אֵינִי יוֹדֵעַ לוֹ פִּתְרוֹן בְּמַחְבֶּרֶת כַּל, וּפִתְרוֹנוֹ לְפִי עִנְיָנוֹ, כְּמוֹ שִׁבֹּלֶת הַנָּהָר:",1,0],[17,25,"בַּת נָחָשׁ. הוּא יִשַׁי אֲבִי דָוִד, רַבּוֹתֵינוּ אָמְרוּ (בבא בתרא יז א): שֶׁמֵּת בְּלֹא עָוֹן, בְּעֶטְיוֹ שֶׁל נָחָשׁ:",1,0],[17,27,"וְשֹׁבִי בֶן נָחָשׁ. הוּא חָנוּן בֶּן נָחָשׁ:",1,0],[17,28,"מִשְׁכָּב. מַצָּעוֹת:",1,0],[17,28,"וְסַפּוֹת. כְּלֵי תַשְׁמִישׁ הֵם, כְּמוֹ ״סִפּוֹת כֶּסֶף״ (מלכים ב יב:יד):",2,0],[17,28,"וְקָלִי. מִינֵי קְלָיוֹת, אָמְרוּ רַבּוֹתֵינוּ (עבודה זרה לח ב): שְׁנֵי מִינֵי שְׁתִיתָא הִקְרִיב בַּרְזִלַּי לְדָוִד, אֶחָד שֶׁל חִטִּים, וְאֶחָד שֶׁל עֲדָשִׁים, כְּעִנְיָן הָאָמוּר כָּאן; קֶמַח וְקָלִי, הוּא שֶׁל דָּגָן, וּפוֹל וַעֲדָשִׁים וְקָלִי, מִמִּינִים שֶׁל קִטְנִיּוֹת שֶׁמְּיַבְּשִׁין אוֹתָן בַּתַּנּוּר כְּשֶׁהֵן לַחִין, וְהֵם מְתוּקִין לְעוֹלָם, וְטוֹחֲנִין אוֹתָן, וְעוֹשִׂין מֵהֶם מַאֲכָל שֶׁקּוֹרִין שְׁתִיתָא:",3,0],[17,29,"וּשְׁפוֹת בָּקָר. (תרגום:) ״וְגוֹבְנִין דְּחָלָב״:",1,0],[18,3,"לֹא יָשִׂימוּ אֵלֵינוּ לֵב. לֹא יִהְיֶה דָבָר חָשׁוּב בְּעֵינֵיהֶם לְהִתְגַּבֵּר וּלְהִתְהַלֵּל, מֵאַחַר שֶׁאֵין אַתָּה בַּמִּלְחָמָה:",1,0],[18,3,"כִּי עַתָּה. בִּהְיוֹתְךָ בִּכְבוֹדְךָ, חָשׁוּב אַתָּה כָּמוֹנוּ:",2,0],[18,3,"עֲשֶׂרֶת אֲלָפִים. כַּעֲשֶׂרֶת אֲלָפִים אִישׁ כָּמוֹנוּ:",3,0],[18,3,"כִּי תִהְיֶה לָּנוּ מֵעִיר לַעְזוֹר. (תרגום:) ״וּכְעַן טָב אֲרֵי תְצַלֵּי עֲלָנָא מִן קַרְתָּא לְמִסְעַד״:",4,0],[18,5,"לְאַט לִי לַנַּעַר. אִם יִקָּרֵא לִפְנֵיכֶם בַּמִּלְחָמָה, חִמְלוּ עָלָיו:",1,0],[18,6,"בְּיַעַר אֶפְרָיִם. וּמֵהֵיכָן הָיָה יַעַר לְאֶפְרַיִם בְּעֵבֶר הַיַּרְדֵּן מִזְרָחָה, שֶׁלֹּא נִתַּן שָׁם חֵלֶק אֶלָּא לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן וְלִמְנַשֶּׁה, אֶלָּא מִתּוֹךְ שֶׁהִתְנָה יְהוֹשֻׁעַ שֶׁיִּהְיוּ מַרְעִין בְּחוֹרָשִׁין, וְהָיָה אוֹתוֹ הַיַּעַר סָמוּךְ לְאֶפְרַיִם, אֶלָּא שֶׁהַיַּרְדֵּן מַפְסִיק, וְהָיוּ מַרְעִין שָׁם בְּהֵמוֹתֵיהֶם, הָיָה נִקְרָא יַעַר אֶפְרָיִם:",1,0],[18,8,"וַיֶּרֶב הַיַּעַר לֶאֱכֹל בָּעָם. חַיּוֹת רָעוֹת שֶׁבַּיַּעַר, כֵּן תִּרְגֵּם יוֹנָתָן:",1,0],[18,9,"וַיִּקָּרֵא אַבְשָׁלוֹם. לְשׁוֹן מִקְרֶה וּפֶגַע:",1,0],[18,9,"וַיֻּתַּן בֵּין הַשָּׁמַיִם וּבֵין הָאָרֶץ. אָמְרוּ רַבּוֹתֵינוּ (סוטה י ב): שָׁלַף חַרְבּוֹ לָקוּץ שְׂעָרוֹ, וְרָאָה גֵּיהִנֹּם פְּתוּחָה תַּחְתָּיו:",2,0],[18,12,"שִׁמְרוּ מִי בַּנַּעַר. כָּל מִי שֶׁיָּבֹא לְיָדוֹ יִשְׁמְרֶנּוּ:",1,0],[18,14,"לֹא כֵן אוֹחִילָה לְפָנֶיךָ. לֹא אֲבַקֵּשׁ עוֹד בַּקָּשָׁה מִמְּךָ, כִּי אֲנִי אֵלֵךְ:",1,0],[18,18,"כִּי אָמַר אֵין לִי בֵן. מְמַלֵּא מְקוֹמִי, וְיִהְיֶה חָשׁוּב כְּמוֹתִי:",1,0],[18,18,"בַּעֲבוּר הַזְכִּיר שְׁמִי. אָקִים לִי מַצֶּבֶת אֶבֶן, וּבִנְיָן חָשׁוּב הָיָה:",2,0],[18,20,"וּבִשַּׂרְתָּ בְּיוֹם אַחֵר. בְּשׂוֹרַת תְּשׁוּעָה אַחֶרֶת:",1,0],[18,20,"כִּי עַל כֵּן. כִּי עַל אֲשֶׁר בֶּן הַמֶּלֶךְ מֵת, לְפִיכָךְ לֹא טוֹבָה לְךָ הַבְּשׂוֹרָה זֹאת:",2,0],[18,22,"וּלְכָה אֵין בְּשׂוֹרָה מוֹצֵאת. אֵין מַתַּת שְׂכַר בְּשׂוֹרָה מְצוּיָה הַיּוֹם:",1,0],[18,23,"וִיהִי מָה. כְּלוֹמַר וּמָה בְּכָךְ אִם אֵין לִי שָׂכָר:",1,0],[18,23,"וַיַּעֲבוֹר. (תרגום:) ״וְקָדִים יָת כּוּשִׁי״:",2,0],[18,29,"רָאִיתִי הֶהָמוֹן הַגָּדוֹל. הוֹמִים וְנָעִים בַּמִּלְחָמָה:",1,0],[18,29,"לִשְׁלוֹחַ אֶת עֶבֶד הַמֶּלֶךְ יוֹאָב וְאֶת עַבְדֶּךָ. הֲרֵי זֶה מִקְרָא מְסוֹרָס, לִשְׁלוֹחַ יוֹאָב אֶת עֶבֶד הַמֶּלֶךְ וְאֶת עַבְדֶּךָ, לְאַחַר שֶׁשָּׁלַח יוֹאָב אֶת עֶבֶד הַמֶּלֶךְ זֶה הָרָץ אַחֲרֵי:",2,0],[18,29,"וְאֶת עַבְדֶּךָ. עַל עַצְמוֹ הוּא אוֹמֵר, וְלֹא יָדַעְתִּי מָה הָיָה אַחֲרֵי כֵן:",3,0],[18,30,"סֹב הִתְיַצֵּב כֹּה. פְּנֵה לְצַד אַחֵר וְהִתְיַצֵּב כֹּה, וְנִשְׁמַע מַה יֹּאמַר זֶה:",1,0],[19,1,"בְּנִי בְנִי. שְׁמוֹנֶה פְּעָמִים, אָמְרוּ רַבּוֹתֵינוּ (סוטה י ב): שִׁבְעָה דְּאַסְקֵיהּ מִשִּׁבְעָה מְדוֹרֵי גֵּיהִנֹּם, וְחַד דְּאַיְיתֵיהּ לְעָלְמָא דְּאָתֵי:",1,0],[19,5,"לָאַט אֶת פָּנָיו. (תרגום:) ״כְּרִיךְ יָת אַפּוֹהִי״, כְּמִשְׁפָּט הָאֲבֵלִים:",1,0],[19,5,"לָאַט. כְּמוֹ ״וַיָּלֶט פָּנָיו בְּאַדַּרְתּוֹ״ (מלכים א יט:יג); ״הִנֵּה הִיא לוּטָה בַשִּׂמְלָה״ (שמואל א כא:י):",2,0],[19,8,"כִּי אֵינְךָ יוֹצֵא. אִם אֵינְךָ יוֹצֵא:",1,0],[19,9,"וְיִשְׂרָאֵל נָס. אוֹתָם שֶׁהָיוּ עִם אַבְשָׁלוֹם:",1,0],[19,10,"כָּל הָעָם נָדוֹן. מִתְוַכְּחִים זֶה עִם זֶה:",1,0],[19,12,"וּדְבַר כָּל יִשְׂרָאֵל בָּא אֶל הַמֶּלֶךְ. כָּל זֶה מִדִּבְרֵי שְׁלִיחוּתוֹ:",1,0],[19,14,"וְלַעֲמָשָׂא. שֶׁהוּא שַׂר צָבָא, תֹּאמְרוּ; הֲלֹא בֶּן אֲחוֹתִי אַתָּה:",1,0],[19,18,"וְצָלְחוּ הַיַּרְדֵּן. (תרגום:) ״בְּקָעוּהוּ בִּתְרִיסֵיהוֹן״:",1,0],[19,19,"וְעָבְרָה הָעֲבָרָה. סְפִינַת הַמַּעְבָּרָה שֶׁעוֹבְרִים בָּהּ אֶת עֵבֶר רֹחַב הַנַּחַל:",1,0],[19,21,"רִאשׁוֹן לְכָל בֵּית יוֹסֵף. כָּל יִשְׂרָאֵל חָטְאוּ לְךָ, וַאֲנִי יוֹתֵר מִכֻּלָּם, וְהִנְנִי בָּאתִי לְבַקֵּשׁ מְחִילָה, אִם תְּקַבְּלֵנִי, בְּטוּחִים כָּל יִשְׂרָאֵל שֶׁתְּקַבְּלֵם, וְאִם לָאו, יִהְיוּ יְרֵאִים לָשׁוּב אֵלֶיךָ עוֹד:",1,0],[19,23,"הַיּוֹם יוּמַת אִישׁ. בִּתְמִיהָ, כִּי הַיּוֹם אֲנִי מֶלֶךְ, עַד עַכְשָׁיו הָיִיתִי סָבוּר, לֹא זִלְזֵל בִּי אָדָם גָּדוֹל כָּזֶה אֶלָּא אִם כֵּן נִפְסְקָה מַלְכוּתִי מֵאֵת הַמָּקוֹם וְהוּא אָמַר לוֹ קַלֵּל אֶת דָּוִד, אֲבָל עַכְשָׁיו שֶׁהוּא מִתְחָרֵט, יָדַעְתִּי כִּי מֶלֶךְ אֲנִי:",1,0],[19,25,"וְלֹא עָשָׂה רַגְלָיו. לְשׁוֹן תִּקּוּן הוּא, הַעֲבָרַת שֵׂעָר שֶׁבֵּין הָרַגְלַיִם:",1,0],[19,25,"שְׂפָמוֹ. גרנו״ן בלע״ז:",2,0],[19,26,"לָמָּה לֹא הָלַכְתָּ עִמִּי. לָצֵאת מִירוּשָׁלַיִם כְּשֶׁיָּצָאתִי:",1,0],[19,27,"כִּי פִסֵּחַ עַבְדֶּךָ. וְאֵינִי יָכוֹל לֵילֵךְ בְּרַגְלִי:",1,0],[19,32,"לְשַׁלְּחוֹ. לְלַוּוֹתוֹ:",1,0],[19,33,"כִּי אִישׁ גָּדוֹל הוּא. בְּעֹשֶׁר:",1,0],[19,35,"כַּמָּה יְמֵי שְׁנֵי חַיַּי. אֲשֶׁר יֵשׁ לִי לִחְיוֹת:",1,0],[19,35,"כִּי אֶעֱלֶה וגו׳. הֲלֹא מְעַט הֵם, וּמָה הֲנָיָה יֵשׁ לִי בְּכִלְכּוּלְךָ:",2,0],[19,36,"הַאֵדַע בֵּין טוֹב לְרָע. בֵּין מַאֲכָל טוֹב לְמַאֲכָל רַע, וְאָמְרוּ רַבּוֹתֵינוּ ז״ל (שבת קנב א): שָׁטוּף בְּזִמָּה הָיָה, לְפִיכָךְ קָפְצָה עָלָיו זִקְנָה:",1,0],[19,37,"כִּמְעַט יַעֲבֹר עַבְדְּךָ. הַלְּוָיָה מוּעֶטֶת יַעֲבֹר עַבְדְּךָ לְלַוּוֹתְךָ, אַחַר שֶׁתַּעֲבֹר אֶת הַיַּרְדֵּן:",1,0],[19,37,"הַגְּמוּלָה הַזֹּאת. שֶׁאֵינָהּ טוֹבָה לִי:",2,0],[19,38,"עַבְדְּךָ כִמְהָם. בְּנוֹ הָיָה:",1,0],[19,43,"כִּי קָרוֹב הַמֶּלֶךְ אֵלַי. מִשִּׁבְטִי הוּא:",1,0],[19,43,"אִם נִשֵּׂאת. כְּמוֹ ״מַשְׂאֵת״ (בראשית מג:לד), פְּרָס מִבֵּית הַמֶּלֶךְ:",2,0],[19,44,"עֶשֶׂר יָדוֹת לִי בַּמֶּלֶךְ. שֶׁאָנוּ עֲשָׂרָה שְׁבָטִים:",1,0],[19,44,"וְגַם בְּדָוִד. אַף עַל פִּי שֶׁהוּא קָרוֹב לָכֶם, אֲנִי מָשׁוּךְ בּוֹ יוֹתֵר מִמְּךָ, שֶׁאֲנִי עֶשֶׂר יָדוֹת:",2,0],[19,44,"וּמַדּוּעַ הֱקִלֹּתַנִי. לִהְיוֹת אַתָּה קוֹדֵם, וְכִי לֹא הָיָה דְבָרִי רִאשׁוֹן לְהָשִׁיב אֶת מַלְכִּי, וְקֹדֶם לָכֵן בָּא דְּבָרֵינוּ אֵלָיו לַהֲשִׁיבוֹ, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה (פסוק יב): ״וּדְבַר כָּל יִשְׂרָאֵל בָּא אֶל הַמֶּלֶךְ״:",3,0],[19,44,"וַיִּקֶשׁ דְּבַר אִישׁ יְהוּדָה. לְשׁוֹן ״הִתְקוֹשְׁשׁוּ״ (צפניה ב:א), נִרְאֶה וְהֻשְׁוָה דְּבַר אִישׁ יְהוּדָה, שֶׁהֶרְאָם אִגֶּרֶת שֶׁשָּׁלַח לָהֶם דָּוִד, ״לָמָּה תִהְיוּ אַחֲרוֹנִים לְהָשִׁיב אֶת הַמֶּלֶךְ וְגוֹ׳״ (לעיל פסוק יב), כָּךְ מְפֹרָשׁ בָּאַגָּדָה. וְיֵשׁ לְפָרֵשׁ, ׳וַיִּקֶשׁ׳, לְשׁוֹן ׳קֹשִׁי וְחֹזֶק׳, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וְתַקִּיף״:",4,0],[20,1,"וְשָׁם נִקְרָא. נִזְדַּמֵּן, לְשׁוֹן ״הִקְדִּישׁ קְרֻאָיו״ (צפניה א:ז); ״וַיִּקְרָא אַבְשָׁלוֹם לְכָל בְּנֵי הַמֶּלֶךְ״ (שמואל ב יג:כג), לְשׁוֹן זִמּוּן:",1,0],[20,4,"הַזְעֶק לִי אֶת אִישׁ יְהוּדָה. שֶׁיִּהְיוּ כָאן עַד שְׁלֹשָׁה יָמִים:",1,0],[20,4,"וְאַתָּה פֹּה עֲמֹד. לְסוֹף שְׁלֹשֶׁת יָמִים הֱוֵי זָהִיר לִהְיוֹת עוֹמֵד כָּאן לְפָנַי, כִּי חָפֵץ הָיָה לִרְדֹּף אַחֲרֵי שֶׁבַע בֶּן בִּכְרִי:",2,0],[20,5,"וַיּוֹחֶר מִן הַמּוֹעֵד. אַשְׁכְּחִינְהוּ לְרַבָּנָן דְּפָתְחוּ בְּמַסֶּכְתָּא, כִּדְאִיתָא בְּסַנְהֶדְרִין (מט א):",1,0],[20,6,"אַתָּה קַח אֶת עַבְדֵי אֲדֹנֶיךָ. אַחֲרֵי אֲשֶׁר אִחֵר עֲמָשָׂא שַׂר הַצָּבָא, וְלֹא הֵבִיא אֶת צְבָא יְהוּדָה, קַח אַתָּה מִן הַנִּמְצָאִים סְבִיבַי, וּרְדֹף אַחֲרָיו:",1,0],[20,6,"וְהִצִּיל עֵינֵינוּ. וְהִצִּיל עַצְמוֹ מֵעֵינֵינוּ, וַהֲרֵי זֶה מִקְרָא קָצָר:",2,0],[20,8,"מְצֻמֶּדֶת עַל מָתְנָיו. סְמוּכָה מְאֹד לְגוּפוֹ לְרֹחַב מָתְנָיו, שֶׁלֹּא כְּדֶרֶךְ חוֹגְרֵי חֶרֶב, כְּדֵי שֶׁתְּהֵא נוֹחָה לִיפּוֹל, וְלֹא יִצְטָרֵךְ לְהוֹצִיאָהּ מִתַּעְרָהּ:",1,0],[20,8,"וְהוּא יָצָא. כְּנֶגֶד עֲמָשָׂא:",2,0],[20,8,"וַתִּפֹּל. הַחֶרֶב מִתַּעְרָהּ, לְפִי שֶׁהָיְתָה חֲלָקָה וּלְטוּשָׁה, וְאֵינָהּ תְּלוּיָה לְצַד יְרֵכוֹ אֶלָּא לְרֹחַב מָתְנָיו, וּכְמְעַט שֶׁשָּׁח עַצְמוֹ לְצַד הָאָרֶץ, נָפְלָה מִתַּעְרָהּ וַאֲחָזָהּ בִּימִינוֹ, וְלֹא הִכִּיר עֲמָשָׂא בַּדָּבָר:",3,0],[20,12,"כַּאֲשֶׁר רָאָה כָּל הַבָּא עָלָיו וְעָמָד. כַּאֲשֶׁר רָאָה הָאִישׁ, שֶׁכָּל הַבָּא עָלָיו הָיָה עוֹמֵד:",1,0],[20,13,"כַּאֲשֶׁר הֹגָה. כַּאֲשֶׁר הֻמְשַׁךְ, כְּמוֹ ״הָגוֹ סִיגִים מִכָּסֶף״ (משלי כה:ד); וּכְמוֹ ״הָגוֹ רָשָׁע לִפְנֵי מֶלֶךְ״ (משלי כה:ה):",1,0],[20,14,"וַיַּעֲבֹר בְּכָל שִׁבְטֵי יִשְׂרָאֵל. שֶׁבַע בֶּן בִּכְרִי, לְפַתּוֹתָם שֶׁיַּמְלִיכוּהוּ עֲלֵיהֶם:",1,0],[20,14,"וְכָל הַבֵּרִים. לֹא יָדַעְתִּי מַהוּ:",2,0],[20,15,"וַתַּעֲמֹד בַּחֵל. (תרגום:) ״וְאַקִּיפוּ מַשְׁרְיָין״. וְיֵשׁ פּוֹתְרִים, וַתַּעֲמֹד בַּחֵל, לְשׁוֹן (איכה ב:ח): ״חֵיל וְחוֹמָה״, הִפִּילוּ הַחוֹמָה הַחִיצוֹנָה, וְנִתְחַזְּקָה לַעֲמֹד עַל יְדֵי הַפְּנִימִית:",1,0],[20,17,"הַאַתָּה יוֹאָב. שֶׁנֶּאֱמַר בְּךָ (שמואל ב כג:ח): ״יוֹשֵׁב בַּשֶּׁבֶת תַּחְכְּמֹנִי״:",1,0],[20,18,"דַּבֵּר יְדַבְּרוּ בָרִאשׁוֹנָה לֵאמֹר. הָיָה לְךָ לְדַבֵּר לְשָׁלוֹם בָּרִאשׁוֹנָה, אִם שָׁלוֹם יַעֲנוּךָ וְיִפְתְּחוּ לְךָ, לֹא הָיָה לְךָ לְהִלָּחֵם עֲלֵיהֶם:",1,0],[20,18,"שָׁאוֹל יְשָׁאֲלוּ בְּאָבֵל. אִם שָׁאֲלוּ בְּנֵי חֵילְךָ בִּשְׁלוֹם הָעִיר הַזֹּאת, שֶׁשְּׁמָהּ אָבֵל:",2,0],[20,18,"וְכֵן הֵתַמּוּ. מִיָּד הָיוּ בְּנֵי הָעִיר מַשְׁלִימִים עִמָּכֶם:",3,0],[20,19,"אָנֹכִי שְׁלֻמֵי אֱמוּנֵי יִשְׂרָאֵל. אֲנִי מִבְּנֵי הָעִיר, שֶׁשְּׁלֵמִים וְנֶאֱמָנִים לְיִשְׂרָאֵל וְלַמֶּלֶךְ וּמִדְרַשׁ אַגָּדָה (בראשית רבה צד ט, ובילקוט שמעוני כא): סֶרַח בַּת אָשֵׁר הָיְתָה, אֲנִי הִשְׁלַמְתִּי נֶאֱמָן לְנֶאֱמָן, עַל יָדִי נִגְלָה אֲרוֹנוֹ שֶׁל יוֹסֵף לְמֹשֶׁה, אֲנִי הִגַּדְתִּי לְיַעֲקֹב כִּי יוֹסֵף חַי:",1,0],[20,20,"חָלִילָה חָלִילָה לִי. חָלִילָה לִי, חָלִילָה לַמֶּלֶךְ:",1,0],[20,21,"נָשָׂא יָדוֹ בַּמֶּלֶךְ בְּדָוִד. בַּמֶּלֶךְ אֲפִלּוּ אֵינוֹ דָוִד, חַיָּב מִיתָה, וּבְדָוִד אֲפִלּוּ אֵינוֹ מֶלֶךְ, חַיָּב מִיתָה, וְכָל שֶׁכֵּן בַּמֶּלֶךְ בְּדָוִד, כָּךְ נִדְרַשׁ בְּמִדְרַשׁ קֹהֶלֶת (ט יח):",1,0],[20,22,"וַתָּבֹא הָאִשָּׁה אֶל כָּל הָעָם בְּחָכְמָתָהּ. שָׁנִינוּ בְּתוֹסֶפְתָּא (תרומות סוף פרק ז): אָמְרָה לָהֶם: הוֹאִיל וְהוּא נֶהֱרָג וְהֵם נֶהֱרָגִין, תְּנוּהוּ לָהֶם, אִם הָיָה יָכוֹל לְהִנָּצֵל, כְּגוֹן שֶׁהוּא מִבִּפְנִים וְאַתֶּם מִבַּחוּץ, וְאַתֶּם בְּסַכָּנָה וְהוּא יָכוֹל לְהִמָּלֵט, אֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ לְהָרְגוֹ בִּשְׁבִיל הַצָּלַתְכֶם, אֲבָל עַכְשָׁו שֶׁגַּם הוּא יֵהָרֵג עִמָּכֶם, הוֹאִיל וְנֶהֶרְסוּ הַחוֹמוֹת וְאֵין כֹּחַ לְהִמָּלֵט, מוּטָב יָמוּת לְבַדּוֹ וְאַל תָּמוּתוּ עִמּוֹ רַבִּי שִׁמְעוֹן אוֹמֵר, כָּךְ אָמְרָה לָהֶם: הַמּוֹרֵד בְּמַלְכוּת בֵּית דָּוִד חַיָּב מִיתָה:",1,0],[20,23,"וְיוֹאָב אֶל כָּל הַצָּבָא. אַף עַל פִּי שֶׁאָמַר דָּוִד עַל עֲמָשָׂא (שמואל ב יט:יד): ״כִּי שַׂר צָבָא אֲשִׂימְךָ תַּחַת יוֹאָב״, עַכְשָׁו שֶׁמֵּת עֲמָשָׂא, לֹא זָז יוֹאָב מִמְּקוֹמוֹ, וְעַל יְדֵי יוֹאָב הֻזְקַק לִמְנוֹת אֶת חֲבֵרָיו:",1,0],[20,26,"עִירָא הַיָּאִרִי. תִּרְגֵּם יוֹנָתָן: ״עִירָא יָאִירָאָה דְּמִן תְּקוֹעַ״. וְכֵן הוּא קָרוּי בְּסֵפֶר הַזֶּה (שמואל ב כג:כו): ״עִירָא בֶן עִקֵּשׁ הַתְּקוֹעִי״. וְ׳יָאִירִי׳ נִקְרָא, עַל שֵׁם שֶׁשָּׁנִינוּ בִּמְנָחוֹת (פה ב): תְּקוֹעַ אַלְפָא לְשֶׁמֶן, שֶׁשֶּׁמֶן זַיִת מָצוּי לְשָׁם, שֶׁמִּמֶּנּוּ מַדְלִיקִין הַנֵּרוֹת:",1,0],[20,26,"הָיָה כֹהֵן לְדָוִד. לוֹ הָיָה נוֹתֵן כָּל מַתְּנוֹת כְּהֻנָּה שֶׁלּוֹ, כָּךְ אָמְרוּ רַבּוֹתֵינוּ (עירובין סג א), וּפְשׁוּטוֹ שֶׁל מִקְרָא, שֶׁעֲשָׂאוֹ שַׂר וְשׁוֹפֵט:",2,0],[21,1,"אֶל שָׁאוּל. עַל עֲוֹן שָׁאוּל שֶׁנִּקְבַּר פִּתְאוֹם בְּהֶחְבֵּא, שֶׁגְּנָבוּהוּ אַנְשֵׁי יָבֵשׁ גִּלְעָד וּקְבָרוּהוּ, וְלֹא נִסְפַּד לְפִי כְּבוֹדוֹ:",1,0],[21,1,"וְאֶל בֵּית הַדָּמִים. שֶׁהָרַג נוֹב עִיר הַכֹּהֲנִים:",2,0],[21,1,"עַל אֲשֶׁר הֵמִית אֶת הַגִּבְעֹנִים. כְּשֶׁהָרַג נוֹב עִיר הַכֹּהֲנִים, הֵמִית מֵהֶם שִׁבְעָה, שְׁנֵי חוֹטְבֵי עֵצִים, וּשְׁנֵי שׁוֹאֲבֵי מַיִם, וְשַׁמָּשׁ וְחַזָּן וְסוֹפֵר, כָּךְ מְפֹרָשׁ בְּגָמָרָא יְרוּשַׁלְמִית בְּסַנְהֶדְרִין (יז) וְרַבּוֹתֵינוּ אָמְרוּ: מִתּוֹךְ שֶׁהָרַג אֶת הַכֹּהֲנִים שֶׁהָיוּ מַסְפִּיקִין לָהֶם מָזוֹן, הֶעֱלָה עָלָיו הַכָּתוּב כְּאִלּוּ הֱמִיתָם. וְאַל תִּתְמַהּ שֶׁהֲרֵי הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹבֵעַ כְּבוֹדוֹ וְתוֹבֵעַ סִרְחוֹנוֹ, שֶׁכָּךְ כָּתוּב (צפניה ב:ג): ״אֲשֶׁר מִשְׁפָּטוֹ פָּעָלוּ״ בַּאֲשֶׁר מִשְׁפָּטוֹ, שָׁם פָּעֳלוֹ, כָּךְ שָׁנִינוּ בִּיבָמוֹת (עח ב):",3,0],[21,2,"וַיֹּאמֶר אֲלֵיהֶם. דִּבְרֵי רִצּוּי, שֶׁיַּעַבְרוּ עַל מִדּוֹתֵיהֶם וְיִמְחֲלוּ לְשָׁאוּל וּלְבֵיתוֹ:",1,0],[21,2,"וְהַגִּבְעֹנִים לֹא מִבְּנֵי יִשְׂרָאֵל הֵמָּה. כְּלוֹמַר וְהֵן הֶרְאוּ בְּעַצְמָם מִדַּת אַכְזָרִיּוּת, שֶׁאֵינָן מִזַּרְעוֹ שֶׁל אַבְרָהָם אָבִינוּ, וְאֵינָן רְאוּיִין לִדָּבֵק בְּיִשְׂרָאֵל, וּלְכָךְ גָּזַר עֲלֵיהֶם דָּוִד שֶׁלֹּא יָבוֹאוּ בַקָּהָל, אָמַר: שְׁלֹשָׁה סִימָנִים יֵשׁ בְּאוּמָּה זוֹ, רַחֲמָנִים וּבַיְשָׁנִים וְגוֹמְלֵי חֲסָדִים, מִי שֶׁיֵּשׁ בּוֹ שְׁלֹשָׁה סִימָנִים הַלָּלוּ, רָאוּי לִדָּבֵק בּוֹ:",2,0],[21,2,"נִשְׁבְּעוּ לָהֶם. בִּימֵי יְהוֹשֻׁעַ כְּשֶׁנְּתָנוּם חוֹטְבֵי עֵצִים וְשׁוֹאֲבֵי מַיִם לַמִּזְבֵּחַ (יהושע ט:טו):",3,0],[21,2,"בְּקַנֹּאתוֹ לִבְנֵי יִשְׂרָאֵל. בְּתִתּוֹ לֵב לְנַקּוֹת וּלְטַהֵר אֶת יִשְׂרָאֵל וְלַעֲשׂוֹת צָרְכֵיהֶם, בִּקֵּשׁ לְהָרְגָם, וְקִנְאָה זוֹ לְטוֹבָה, כְּמוֹ (במדבר יא:כט): ״הַמְקַנֵּא אַתָּה לִי״; וְכֵן (מלכים ב י:טז): ״בְּקִנְאָתִי לַה׳״ דְּיֵהוּא זֶהוּ פְשׁוּטוֹ. וּלְפִי מִדְרָשׁוֹ, לֹא אָמַר לַהֲרוֹג אֶלָּא אֶת הַכֹּהֲנִים, וְקִנְאָה זוֹ הָאֲמוּרָה כָּאן, אֵינָהּ לְטוֹבָה כִּי אִם לְרָעָה, שֶׁיָּדַע שֶׁלֹּא תִּמְשׁוֹךְ מַלְכוּתוֹ מִיּוֹם שֶׁלֹּא שָׁמַר מִצְוַת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּעֲמָלֵק, וּמֵאָז נִתְקַנֵּא בָּהֶם:",4,0],[21,3,"וּבָרְכוּ אֶת נַחֲלַת ה׳. הִתְפַּלְּלוּ עֲלֵיהֶם:",1,0],[21,4,"אֵין לָנוּ כֶּסֶף וְזָהָב עִם שָׁאוּל. כִּי אִם נְפָשׁוֹת, בִּקֵּשׁ לְפַיְּסָם בְּמָמוֹן, וְלֹא רָצוּ, אָמַר שֶׁמָּא הֵם מִתְבַּיְּשִׁין זֶה מִזֶּה, הָלַךְ וּפִיֵּס כָּל אֶחָד וְאֶחָד לְעַצְמוֹ, וְלֹא נִתְפַּיְּסוּ, לְכָךְ כְּתִיב: אֵין לִי כֶּסֶף וְזָהָב וְגוֹ׳, לְשׁוֹן יָחִיד, זוֹ רָאִיתִי בִּירוּשַׁלְמִי (סנהדרין ו:ז):",1,0],[21,4,"וְאֵין לָנוּ אִישׁ לְהָמִית. בְּכָל שְׁאָר בְּנֵי יִשְׂרָאֵל, שֶׁלֹּא חָטְאוּ לָנוּ:",2,0],[21,5,"וַאֲשֶׁר דִּמָּה לָנוּ נִשְׁמַדְנוּ. אֲשֶׁר אָמַר בְּלִבּוֹ, שֶׁנִּשְׁמַדְנוּ עַל יָדוֹ מֵהִתְיַצֵּב וְגוֹ׳, שֶׁחָשַׁב לְהַשְׁמִידֵנוּ:",1,0],[21,5,"דִּמָּה לָנוּ. חָשַׁב עָלֵינוּ לְהַשְׁמִידֵנוּ:",2,0],[21,6,"וְהוֹקַעֲנוּם. תְּלִיָּה:",1,0],[21,6,"לַה׳. לִשְׁמוֹ שֶׁל מָקוֹם, לְהוֹדִיעַ מִשְׁפָּטוֹ:",2,0],[21,6,"בְּחִיר ה׳. בַּת קוֹל יָצְאָה וְאָמְרָה: בְּחִיר ה׳ (ברכות יב ב):",3,0],[21,7,"וַיַּחְמֹל הַמֶּלֶךְ. בִּקֵּשׁ רַחֲמִים שֶׁלֹּא יִקְלְטֶנּוּ הָאָרוֹן, שֶׁהֶעֱבִירָם לִפְנֵי הָאָרוֹן, כָּל שֶׁהָאָרוֹן קוֹלְטוֹ, לְמִיתָה (יבמות עט א):",1,0],[21,8,"בְּנֵי מִיכַל בַּת שָׁאוּל אֲשֶׁר יָלְדָה לְעַדְרִיאֵל. וְכִי מִיכַל יָלְדָה, וַהֲלֹא מֵירַב יָלְדָה לוֹ, אֶלָּא מֵירַב יָלְדָה, וּמִיכַל גִּדְּלָה, לְפִיכָךְ נִקְרָא עַל שְׁמָהּ, וְהַמְגַדֵּל יָתוֹם וִיתוֹמָה בְּתוֹךְ בֵּיתוֹ, כְּאִלּוּ יְלָדוֹ וְנִקְרָא עַל שְׁמוֹ (סנהדרין יט ב):",1,0],[21,9,"בִּתְחִלַּת קְצִיר. בִּימֵי נִיסָן:",1,0],[21,10,"עַד נִתַּךְ מַיִם. בִּימוֹת הַגְּשָׁמִים בְּתִשְׁרֵי, שֶׁלֹּא נִתְּנוּ לִקְבוּרָה וַהֲלֹא כְתִיב (דברים כא:כג): ״לֹא תָלִין נִבְלָתוֹ״, אֶלָּא אָמְרוּ מוּטָב תֵּעָקֵר אוֹת אַחַת מִן הַתּוֹרָה, וְיִתְקַדֵּשׁ שֵׁם שָׁמַיִם בְּפַרְהֶסְיָא, שֶׁהָיוּ עוֹבְרִין וְשָׁבִין אוֹמְרִים: מַה טִיבָן שֶׁל אֵלּוּ, אוֹמְרִים לָהֶם: מִבְּנֵי מְלָכִים הֵם, וּמֶה עָשׂוּ, פָּשְׁטוּ יָדָם בְּגֵרִים גְּרוּרִים, אוֹמְרִים: אֵין לְךָ אֻמָּה רְאוּיָה לִדָּבֵק בָּהּ כְּאֻמָּה זוֹ (יבמות עט א):",1,0],[21,12,"וַיִּקַּח אֶת עַצְמוֹת שָׁאוּל. שֶׁנֶּאֱמַר לוֹ עֲלֵיהֶם ׳אֶל שָׁאוּל׳, שֶׁלֹּא נִסְפַּד כַּהֲלָכָה:",1,0],[21,13,"וַיַּאַסְפוּ אֶת עַצְמוֹת. שִׁבְעָה הַמּוּקָעִין:",1,0],[21,14,"כָּל אֲשֶׁר צִוָּה הַמֶּלֶךְ. לְהַסְפִּיד עֲלֵיהֶם בְּכָל עָרֵי יִשְׂרָאֵל:",1,0],[21,16,"וּמִשְׁקַל קֵינוֹ. הוּא כְּמוֹ תִּיק שֶׁבְּרֹאשׁ בֵּית יָד הָרוֹמַח שֶׁקּוֹרִין ארישטוי״ל בלע״ז, וְעָשׂוּי כְּכוֹבַע, וְיֵשׁ דּוּגְמָתוֹ בִּזְבָחִים (פח ב, עיין שיטה מקובצת שם): רִמּוֹנֵי הַמְּעִיל לְמָה הֵם דּוֹמִין, כְּמִין קוֹלָסוֹת שֶׁבְּרָאשֵׁי הַתִּינוֹקוֹת, ׳קוֹלָסוֹת׳ היילמ״ש בלע״ז:",1,0],[21,16,"וְהוּא חָגוּר. חֲגוֹרָה חֲדָשָׁה. וְשָׁמַעְתִּי, שֶׁאוֹתוֹ הַיּוֹם נִתְחַנֵּךְ לִלְבּוֹשׁ כְּלֵי מִלְחָמָה, וְדֶרֶךְ הַמְחֻנָּכִים לַעֲשׂוֹת נִצָּחוֹן וּגְבוּרָה בְּיוֹם חִנּוּכָם, לִקְנוֹת שֵׁם, לְכָךְ וַיֹּאמֶר לְהַכּוֹת אֶת דָּוִד:",2,0],[21,17,"וַיַּעֲזָר לוֹ. שֶׁעֲזָרוֹ בִּתְפִלָּה, כִּדְאִיתָא בְּחֵלֶק (סנהדרין צה א):",1,0],[21,18,"וַתְּהִי עוֹד הַמִּלְחָמָה. כְּבָר קָדְמָה זוֹ לְכֻלָּן, וְלֹא מְנָאָה כָּאן, אֶלָּא לְצָרֵף מִיתַת אַרְבָּעָה בְּנֵי עָרְפָה:",1,0],[21,19,"אֶלְחָנָן. דָּוִד:",1,0],[21,19,"בֶּן יַעְרֵי אֹרְגִים. שֶׁהָיוּ מִשְׁפַּחְתּוֹ אוֹרְגִים פָּרֹכֶת לַמִּקְדָּשׁ הַקָּרוּי יַעַר:",2,0],[21,19,"כִּמְנוֹר אֹרְגִים. (תרגום:) ״כְּאַכְסָן דְּגַרְדָאִין״, הַקָּרוּי אינשובל״א בלע״ז, תָּבֹא אֲרִיגָה וְתַעֲמֹד כְּנֶגֶד אֲרִיגָה:",3,0],[21,20,"אִישׁ מָדוֹן. כְּתַרְגּוּמוֹ: ״גְּבַר דְּמִשְׁחָן״. שֶׁאֵין עִקַּר הַתֵּבָה אֶלָּא מ״ם וְדָלֶ״ת, כְּמוֹ מ״שְּׁאוֹן״ (תהלים סה:ח), שִׁי״ן וְאָלֶ״ף: וּמ״הֲמוֹן״(בראשית יז:ד), הֵ״א וּמֵ״ם. וּבְדִבְרֵי הַיָּמִים (דברי הימים א יא:כג) כְּתִיב: ״אִישׁ מִדָּה״, כְּלוֹמַר גָּבוֹהַּ מְאֹד, שֶׁאוֹמְדִין כַּמָּה מִדָּתוֹ:",1,0],[21,20,"שֵׁשׁ וָשֵׁשׁ וְגוֹ׳. פֵּרְשׁוּ רַבּוֹתֵינוּ בִּבְכוֹרוֹת (מה ב) שֶׁהֻצְרַךְ לוֹמַר עֶשְׂרִים וְאַרְבַּע, שֶׁלֹּא תֹּאמַר אֶצְבְּעוֹת שְׁתֵּי יָדָיו אֵינָן אֶלָּא שֵׁשׁ, וְאֶצְבְּעוֹת רַגְלָיו אֵינָן אֶלָּא שֵׁשׁ, לְכָךְ נֶאֱמַר עֶשְׂרִים וְאַרְבַּע, וְאִם כָּתַב עֶשְׂרִים וְאַרְבַּע וְלֹא אָמַר שֵׁשׁ וָשֵׁשׁ, הָיִיתִי אוֹמֵר שִׁבְעָה בְּאַחַת, וַחֲמִשָּׁה בְּאַחַת, וּמַהוּ ׳מִסְפָּר׳, שֶׁכֻּלָּן הָיוּ נִסְפָּרוֹת בְּסֵדֶר הָאֶצְבָּעוֹת בְּגַב הַיָּד:",2,0],[22,1,"בְּיוֹם הִצִּיל ה׳ אוֹתוֹ. לְעֵת זִקְנָתוֹ, לְאַחַר שֶׁעָבְרוּ עָלָיו כָּל צָרוֹתָיו וְנִצּוֹל מִכֻּלָּם:",1,0],[22,1,"וּמִכַּף שָׁאוּל. וַהֲלֹא שָׁאוּל בַּכְּלָל הָיָה, אֶלָּא שֶׁהָיָה אוֹיְבוֹ וְרוֹדְפוֹ מִכֻּלָּם, כַּיּוֹצֵא בּוֹ (שמואל ב ב:ל): ״תִּשְׁעָה עָשָׂר אִישׁ וַעֲשָׂהאֵל״, כַּיּוֹצֵא בּוֹ (יהושע ב:א): ״לְכוּ רְאוּ אֶת הָאָרֶץ וְאֶת יְרִיחוֹ״ וְכַיּוֹצֵא בּוֹ (מלכים א יא:א): ״וְהַמֶּלֶךְ שְׁלֹמֹה אָהַב נָשִׁים נָכְרִיּוֹת וְאֶת בַּת פַּרְעֹה״:",2,0],[22,2,"סַלְעִי וּמְצוּדָתִי. לְשׁוֹן חוֹזֶק הֵם, ׳סֶלַע׳ כְּמַשְׁמָעוֹ, ׳מְצוּדָה׳ הִיא מְצוּדַת יְעָרִים, שֶׁקּוֹרִין פליישאי״ן בלע״ז, וְעַל שֵׁם הַנֵּס שֶׁנַּעֲשָׂה לוֹ בְּסֶלַע הַמַּחְלוֹקֶת (שמואל א כג:כח), וְהַמְּצוּדוֹת בַּחוֹרְשָׁה:",1,0],[22,2,"וּמְפַלְּטִי לִי. מְפַלְּטִי עִם צְבָא יִשְׂרָאֵל בַּמִּלְחָמָה, וּפְעָמִים שֶׁהוּא מְפַלֵּט לִי כְּשֶׁאֲנִי לְבַדִּי, כְּגוֹן מִן יִשְׁבִּי בְּנוֹב (שמואל ב כא:טז):",2,0],[22,3,"צוּרִי. לְשׁוֹן סֶלַע, שֶׁהַסֶּלַע מַחֲסֶה לְעוֹבְרֵי דֶרֶךְ, מִן הַמָּטָר וְהָרוּחוֹת, אבריאמ״ש בלע״ז:",1,0],[22,3,"אֶחֱסֶה. לְשׁוֹן כִּסּוּי, שֶׁהָיִיתִי מִתְכַּסֶּה לְעֶזְרָה:",2,0],[22,3,"מִשְׂגַּבִּי. סוֹמְכֵנִי:",3,0],[22,3,"וּמְנוּסִי. שֶׁהָיִיתִי נָס אֵלָיו לְעֶזְרָה:",4,0],[22,4,"מְהֻלָּל אֶקְרָא ה׳. כְּתַרְגּוּמוֹ; בְּקָרְאִי לוֹ אֲהוֹדֶנּוּ, לְפִי כִּי מֵאוֹיְבַי אֲנִי בּוֹטֵחַ שֶׁאִוָּשַׁע. וְיִתָּכֵן לִפְתּוֹר אֶקְרָא וְאִוָּשַׁע, לְשׁוֹן ׳הוֹוֶה׳:",1,0],[22,5,"אֲפָפוּנִי. הִקִּיפוּנִי:",1,0],[22,5,"מִשְׁבְּרֵי מָוֶת. כְּתַרְגּוּמוֹ: ״כְּאִתָּא דְּיָתְבָא עַל מַתְבְּרָא״, כֵּן שֵׁם מוֹשַׁב הָאֲבָנִים שֶׁהָאִשָּׁה יוֹלֶדֶת שָׁם:",2,0],[22,5,"נַחֲלֵי. גְּיָסוֹת שׁוֹטְפוֹת כְּנַחַל:",3,0],[22,6,"חֶבְלֵי. כְּתַרְגּוּמוֹ: ״מַשְׁרִית״, כְּמוֹ (שמואל א י:ה): ״חֶבֶל נְבִיאִים״:",1,0],[22,6,"קִדְּמוּנִי. בָּאוּ לְפָנַי:",2,0],[22,7,"בַּצַּר לִי אֶקְרָא ה׳ וַיִּשְׁמַע וְגוֹ׳. כָּךְ דֶּרֶךְ לְשׁוֹן הוֹוֶה, מְדַבֵּר לְשׁוֹן עָבָר וּלְשׁוֹן עָתִיד בְּפַעַם אַחַת:",1,0],[22,8,"וַיִּתְגָּעַשׁ וַתִּרְעַשׁ. לֹא עַל נִסִּים שֶׁאֵרְעוּהוּ נֶאֱמַר, אֶלָּא עַל נִסִּים שֶׁנַּעֲשׂוּ לְיִשְׂרָאֵל, וְרֹאשׁ הַמִּקְרָא מְחֻבָּר עַל סוֹפוֹ:",1,0],[22,8,"כִּי חָרָה לוֹ. ׳כִּי׳ מְשַׁמֵּשׁ כָּאן בִּלְשׁוֹן ׳כַּאֲשֶׁר׳, וְכֵן פִּתְרוֹנוֹ, וּכְשֶׁחָרָה לוֹ מִפְּנֵי מַכְעִיסָיו, נִתְגַּעֲשָׁה וְנִתְרַעֲשָׁה הָאָרֶץ, וּמוֹסְדוֹת הַשָּׁמַיִם רָגְזוּ וְרָעֲשׁוּ:",2,0],[22,9,"עָלָה עָשָׁן בְּאַפּוֹ. כֵּן דֶּרֶךְ הַכּוֹעֵס, יוֹצֵא עָשָׁן מִנְּחִירָיו, וְכֵן (תהלים יח:ט): ״עָלָה עָשָׁן בְּאַפּוֹ״. וְזֶהוּ כָּל לְשׁוֹן חֲרוֹן אַף, שֶׁהָאַף נוֹחֵר וּמַעֲלֶה הֶבֶל:",1,0],[22,9,"וְאֵשׁ מִפִּיו תֹּאכֵל. מִגִּזְרַת דְּבַר פִּיו, תֹּאכַל אֵשׁ בָּרְשָׁעִים:",2,0],[22,10,"וַיֵּט שָׁמַיִם. לְהִנָּקֵם מֵאוֹיְבָיו, מִמִּצְרַיִם וּמִפַּרְעֹה:",1,0],[22,12,"וַיָּשֶׁת חֹשֶׁךְ סְבִיבוֹתָיו. לְסֻכָּה, כָּעִנְיָן שֶׁנֶּאֱמַר (שמות יד:כ): ״וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ״, מַפְסִיק בֵּין מִצְרַיִם לְיִשְׂרָאֵל:",1,0],[22,12,"חַשְׁרַת מַיִם עָבֵי שְׁחָקִים. מֵאַיִן הָיָה הַחֹשֶׁךְ, עָבֵי שְׁחָקִים הָיוּ, שֶׁהֵן חוֹשְׁרִין מַיִם עַל הָאָרֶץ:",2,0],[22,12,"חַשְׁרַת. לְשׁוֹן כְּבָרָה הוּא, שֶׁהוּא נוֹפֵל עַל הָאָרֶץ דַּק דַּק (תענית ט ב), וְכֵן הוּא אוֹמֵר בְּאַגָּדוֹת הַרְבֵּה: חוֹשְׁרִין אוֹתוֹ בִּכְבָרָה. וְיֵשׁ לִפְתּוֹר ׳חַשְׁרַת׳, לְשׁוֹן ׳קֶשֶׁר׳, שֶׁמִּתְקַשְּׁרִין הַשָּׁמַיִם בְּעָבִים עַל יְדֵי הַמַּיִם, כְּמוֹ ׳וְחִשּׁוּרֵיהֶם׳ הָאָמוּר בְּאוֹפַנֵּי הַמְּכוֹנָה (מלכים א ז:לג), שֶׁהֵם זְרוֹעוֹת הָעֵץ הַמְהַדְּקִין וְקוֹשְׁרִין עִגּוּלֶיהָ יַחַד:",3,0],[22,13,"מִנֹּגַהּ נֶגְדּוֹ. שֶׁלֹּא תֹאמַר בַּחֹשֶׁךְ הוּא שָׁרוּי, אֶלָּא הַנֹּגַהּ לִפְנִים מִן הַמְּחִיצָה, וּמֵאוֹתוֹ נֹגַהּ אֲשֶׁר לְפָנָיו, בָּעֲרוּ גַּחֲלֵי אֵשׁ, שֶׁנִּשְׁתַּלְּחוּ חִצִּים עַל מִצְרַיִם:",1,0],[22,16,"יִגָּלוּ מוֹסְדוֹת תֵּבֵל. שֶׁנִּבְקַע הַתְּהוֹם, כְּשֶׁנִּבְקַע יַם סוּף נִבְקְעוּ כָּל מֵימוֹת שֶׁבָּעוֹלָם (ילקוט שמעוני רמז קסא):",1,0],[22,16,"מִנִּשְׁמַת. מִכֹּחַ נְשִׁיבַת רוּחַ אַפּוֹ:",2,0],[22,18,"כִּי אָמְצוּ. כַּאֲשֶׁר אָמְצוּ:",1,0],[22,21,"כְּצִדְקָתִי. כְּשֶׁיָּצְאוּ אַחֲרָיו לַמִּדְבָּר וְסָמְכוּ עַל הַבְטָחָתוֹ:",1,0],[22,26,"חָסִיד, תָּמִים, נָבָר. כְּנֶגֶד שְׁלֹשָׁה אָבוֹת, שֶׁשִּׁלֵּם הַקָּדוֹשׁ בָּרוּךְ הוּא גְּמוּל צִדְקָתָם לִבְנֵיהֶם:",1,0],[22,27,"וְעִם עִקֵּשׁ. פַּרְעֹה:",1,0],[22,27,"תִּתַּפָּל. לְשׁוֹן נִפְתָּל וְעִקֵּשׁ, וּבְסֵפֶר תְּהִלִּים (תהלים יח:כז) כָּתוּב: ״תִּתְפַּתָּל״. דָּבָר אַחֵר: יִשְׁלַח מִמָּרוֹם יִקָּחֵנִי. עַל עַצְמוֹ אָמַר, כְּשֶׁהָיָה נֶחְפָּז לָלֶכֶת מִפְּנֵי שָׁאוּל בְּסֶלַע הַמַּחְלְקוֹת וְהָיָה קָרוֹב לְהִתָּפֵשׂ, וּמַלְאָךְ בָּא אֶל שָׁאוּל לֵאמֹר: מַהֲרָה וְלֵכָה כִּי פָשְׁטוּ פְלִשְׁתִּים: וַיָּשֶׁב וְגוֹ׳ כְּצִדְקָתִי. שֶׁלֹּא הֲרַגְתִּיו בְּכָרְתִי כְּנַף מְעִילוֹ:",2,0],[22,31,"אִמְרַת ה׳ צְרוּפָה. בְּרוּרָה, מַבְטִיחַ וְעוֹשֶׂה:",1,0],[22,33,"וַיַּתֵּר תָּמִים דַּרְכִּי. מִכָּל מִכְשׁוֹל, וּמִכָּל חֵטְא, וּמִכָּל מְסֻכָּן, עַד כִּי הָיָה שָׁלֵם וְכָבוּשׁ:",1,0],[22,35,"וְנִחַת קֶשֶׁת נְחוּשָׁה זְרֹעֹתָי. וְנִדְרְכָה קֶשֶׁת נְחוּשָׁה עַל זְרוֹעִי, שֶׁיֵּשׁ בִּי כֹּחַ לְדָרְכָהּ. קְשָׁתוֹת הָיוּ תְּלוּיִם לְדָוִד בְּבֵיתוֹ, וְהָיוּ מַלְכֵי הָאֻמּוֹת בָּאִין וְרוֹאִין אוֹתָן, וְאוֹמְרִים זֶה לָזֶה: אַתָּה סָבוּר שֶׁהוּא יָכוֹל לְדָרְכָן, אֵין זֶה אֶלָּא לְיָרְאֵנוּ, וְדָוִד שׁוֹמֵעַ וְנוֹטְלָן וּמְכַתְּתָן לִפְנֵיהֶם. וּדְרִיכַת קֶשֶׁת לְשׁוֹן חַיִּת הִיא, וְכֵן ״תְּהִלִּים חִצֶּיךָ נִחְתּוּ בִי״:",1,0],[22,36,"וַעֲנֹתְךָ תַּרְבֵּנִי. הִגְדַּלְתָּ לִי מִדַּת עַנְוְתָנוּתְךָ:",1,0],[22,37,"תַּרְחִיב צַעֲדִי. כְּשֶׁאָדָם מְדַבֵּק רַגְלָיו זוֹ בָּזוֹ, הוּא נוֹחַ לִפּוֹל, וְכֵן הוּא אוֹמֵר (משלי ד:יב): ״בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ״:",1,0],[22,37,"קַרְסֻלָּי. עֲקֵבַי:",2,0],[22,42,"יִשְׁעוּ וְאֵין מוֹשִׁיעַ וְגוֹ׳. הֲרֵי זֶה מִקְרָא מְסֹרָס, יִשְׁעוּ אֶל ה׳ וְלֹא עָנָם, וְאֵין מוֹשִׁיעַ, כְּמוֹ (ישעיהו יז:ז): ״יִשְׁעֶה הָאָדָם אֶל עֹשֵׂהוּ״, כְּמוֹ יִפְנֶה. וּמְנַחֵם חִבְּרוֹ עִם (בראשית ד:ד): ״וַיִּשַׁע ה׳ אֶל הֶבֶל״, וּפָתַר בּוֹ לְשׁוֹן עֲתִירָה, וְנוֹפֵל הַלָּשׁוֹן עַל הַמַּעְתִּיר וְעַל הַנֶּעְתָּר, כְּמוֹ (בראשית כה:כא): ״וַיֶּעְתַּר יִצְחָק לַה׳״, ״וַיֵּעָתֶר לוֹ ה׳״, אַף כָּאן ״יִשְׁעוּ וְאֵין מוֹשִׁיעַ״ נוֹפֵל עַל הַמִּתְפַּלֵּל, וַיִּשַׁע ה׳ נוֹפֵל עַל הַלָּשׁוֹן, עַל מִי שֶׁמִּתְפַּלְּלִין לְפָנָיו:",1,0],[22,43,"אֶרְקָעֵם. אֶרְמְסֵם, וְהַרְבֵּה יֵשׁ בְּסֵפֶר יְחֶזְקֵאל: (ו:יא): ״וּרְקַע בְּרַגְלְךָ״ (כה:ו): ״וְרַקְעֲךָ בְּרָגֶל״:",1,0],[22,44,"מֵרִיבֵי. מִדּוֹאֵג, מֵאֲחִיתֹפֶל, וְשָׁאוּל, וְהַזִּיפִים:",1,0],[22,44,"תִּשְׁמְרֵנִי לְרֹאשׁ גּוֹיִם. צְפַנְתַּנִי לְכָךְ. וּמִדְרַשׁ אַגָּדָה; אָמַר דָּוִד: רִבּוֹנוֹ שֶׁל עוֹלָם, הַצִּילֵנִי מִדִּינוֹ שֶׁל יִשְׂרָאֵל, שֶׁאִם אַטְהוּ אוֹ אֶרְדֶּה אֶת יִשְׂרָאֵל בַּעֲבוֹדָתוֹ, אֲנִי נֶעֱנָשׁ, אֶלָּא לְרֹאשׁ הַפְּלִשְׁתִּים תְּשִׂימֵנִי, וְהֵם יַעַבְדוּנִי, וַעֲלֵיהֶם לֹא אֶעֱנָשׁ:",2,0],[22,45,"יִתְכַּחֲשׁוּ לִי. מֵחֲמַת יִרְאָה, יֹאמְרוּ לִי כְּזָבִים:",1,0],[22,45,"לִשְׁמוֹעַ אֹזֶן יִשָּׁמְעוּ לִי. אֲפִלּוּ שֶׁלֹּא בְּפָנַי, יָגוּרוּ מִפָּנַי, לְמִשְׁמַע אָזְנֵיהֶם לָסוּר אֶל מִשְׁמַעְתִּי:",2,0],[22,46,"בְּנֵי נֵכָר יִבֹּלוּ. יִלְאוּ, לְשׁוֹן (ירמיהו ח:יג): ״וְהֶעָלֶה נָבֵל״ פלישטירונ״ט בלע״ז:",1,0],[22,46,"וְיַחְגְּרוּ. לְשׁוֹן פִּסְחִים:",2,0],[22,46,"מִמִּסְגְּרוֹתָם. מִקֹּשִׁי יִסּוּרֵי מַסְגֵּר שֶׁאֲנִי מְיַסְּרָן בָּהֶם:",3,0],[22,47,"חַי ה׳. הָעוֹשֶׂה לִי אֵלֶּה:",1,0],[23,1,"וְאֵלֶּה דִּבְרֵי דָוִד. נְבוּאַת דָּוִד אַחֲרוֹנִים, וּמִי הֵם הָרִאשׁוֹנִים, דִּבְרֵי הַשִּׁירָה הָאֲמוּרִים לְמַעְלָה, אֲבָל בְּכָל שִׁירוֹת וְתִשְׁבָּחוֹת שֶׁאָמַר, אֵין נִקְרָאִים דְּבָרִים:",1,0],[23,1,"הוּקַם עָל. הוּקַם לְמַעְלָה:",2,0],[23,1,"וּנְעִים זְמִירוֹת יִשְׂרָאֵל. אֵין יִשְׂרָאֵל מְשׁוֹרְרִים בַּמִּקְדָּשׁ, אֶלָּא שִׁירוֹתָיו וּזְמִירוֹתָיו:",3,0],[23,2,"דִּבֶּר בִּי. הִשְׁרָה בִּי רוּחַ קָדְשׁוֹ וְנִדְבַּר בִּי, וְכָל לְשׁוֹן נְבוּאָה, נוֹפֵל בּוֹ לְשׁוֹן דִּבּוּר, כְּמוֹ (במדבר יב:ב): ״הֲרַק אַךְ בְּמֹשֶׁה דִּבֶּר הֲלֹא גַּם בָּנוּ דִּבֶּר״ (במדבר יב:ו): ״אֲדַבֶּר בּוֹ״, וְטַעְמוֹ שֶׁל דָּבָר לְפִי שֶׁהָרוּחַ נִכְנָס בּוֹ בְּקֶרֶב הַנָּבִיא, וּמְדַבֵּר בּוֹ:",1,0],[23,3,"לִי דִּבֶּר צוּר יִשְׂרָאֵל. אֵלַי דִּבֶּר וְצִוָּה צוּר יִשְׂרָאֵל, שֶׁאֶהְיֶה מוֹשֵׁל בָּאָדָם, בְּיִשְׂרָאֵל שֶׁנִּקְרְאוּ אָדָם, שֶׁנֶּאֱמַר (יחזקאל לד:לא): ״אָדָם אַתֶּם״ (יבמות סא א), וְאֶהְיֶה צַדִּיק מוֹשֵׁל וִירֵא אֱלֹהִים. וְרַבּוֹתֵינוּ (מועד קטן טז ב) פֵּרְשׁוּהוּ בְּלָשׁוֹן אַחֵר: אָמַר דָּוִד: אֱלֹהֵי יִשְׂרָאֵל לִי דִּבֶּר, אֵלַי דִּבֶּר צוּר יִשְׂרָאֵל, מוֹשֵׁל בָּאָדָם אֲנִי, וּמִי מוֹשֵׁל בִּי, צַדִּיק, שֶׁאֲנִי גּוֹזֵר גְּזֵרָה וְהוּא מְבַטְּלָהּ. אֲבָל לְפִי יִשּׁוּב הַמִּקְרָאוֹת, הָרִאשׁוֹן הוּא פְּשׁוּטוֹ שֶׁל מִקְרָא:",1,0],[23,4,"וּכְאוֹר בֹּקֶר יִזְרַח שָׁמֶשׁ. וְהִבְטִיחֵנִי שֶׁתֵּלֵךְ גְּדֻלָּתִי הָלוֹךְ וְגָדֵל, כְּאוֹר נֹגַהּ אֲשֶׁר הוֹלֵךְ וָאוֹר:",1,0],[23,4,"בֹּקֶר לֹא עָבוֹת. אוֹר שֶׁאֵינוֹ אָפֵל:",2,0],[23,4,"מִנֹּגַהּ מִמָּטָר דֶּשֶׁא מֵאָרֶץ. מֵאִיר בָּקְרִי יוֹתֵר מִנֹּגַהּ הַבָּא מִמָּטָר, כְּחֹם צַח עֲלֵי אוֹר, כְּשֶׁהַמָּטָר יוֹרֵד עַל הָאָרֶץ מְלֵאָה דְשָׁאִים, וְהַשֶּׁמֶשׁ זוֹרֵחַ עָלָיו וּמַבְהִיק, וְכֵן פִּתְרוֹנוֹ, יוֹתֵר מִנֹּגַהּ הַבָּא מִמָּטָר שֶׁל דֶּשֶׁא מֵאָרֶץ:",3,0],[23,5,"כִּי לֹא כֵן בֵּיתִי עִם אֵל. שֶׁיְּהֵא בָּקְרִי עָבוֹת:",1,0],[23,5,"כִּי בְרִית עוֹלָם. הַתּוֹרָה אֲשֶׁר שָׂם לִי, עֲרוּכָה בְּכָל בֵּיתִי וּשְׁמוּרָה:",2,0],[23,5,"כִּי כָל יִשְׁעִי וְכָל חֵפֶץ. צְרָכַי מוּכָנִים לְפָנָיו, וַהֲרֵי זֶה מִקְרָא קָצָר:",3,0],[23,5,"כִּי לֹא יַצְמִיחַ. עוֹד לְמֶלֶךְ אַחַר מַלְכוּתִי. דָּבָר אַחֵר: כִּי בְרִית עוֹלָם שָׂם לְבֵיתִי, לִהְיוֹת מַלְכוּתִי קַיֶּמֶת, וְהַבְּרִית עֲרוּכָה בַכֹּל, בְּפִי כָּל הַנְּבִיאִים:",4,0],[23,6,"כְּקוֹץ מֻנָּד. קרדו״ן בלע״ז, שֶׁבְּקַטְנוּתוֹ רַךְ נָע וָנָד, וְסוֹפוֹ מִתְקַשֶּׁה, עַד אֲשֶׁר לֹא בְיָד יִקָּחֻהוּ:",1,0],[23,7,"וְאִישׁ יִגַּע בָּהֶם יִמָּלֵא. צָרִיךְ שֶׁיִּלְבַּשׁ אֶת בְּשָׂרוֹ בַּרְזֶל, וִימַלֵּא יָדוֹ בִּכְלֵי זַיִן לְקַצְּצוֹ:",1,0],[23,7,"וּבָאֵשׁ שָׂרוֹף יִשָּׂרְפוּ בַּשָּׁבֶת. וְאֵין שָׁם תַּקָּנָה אֶלָּא שְׂרֵפָה, וְלָשֶׁבֶת וּלְהִתְחַמֵּם כְּנֶגְדָּם, כָּךְ הָרְשָׁעִים אֵין לָהֶם תַּקָּנָה, אֶלָּא שְׂרֵפָה בְּגֵיהִנֹּם:",2,0],[23,7,"בַּשָּׁבֶת. הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל כִּסֵּא הַדִּין:",3,0],[23,8,"אֲשֶׁר לְדָוִד יוֹשֵׁב בַּשֶּׁבֶת. יוֹשֵׁב בְּשֶׁבֶת סַנְהֶדְרִין, וְהוּא תַּחְכְּמוֹנִי, וְהוּא רֹאשׁ הַשָּׁלִישִׁי, אָב בָּנוּי בְּחָכְמָה וּבִגְבוּרָה, בִּשְׁלֹשָׁה דְּבָרִים הַלָּלוּ הוּא רֹאשׁ, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א טז:יח): ״וּנְבוֹן דָּבָר וְאִישׁ תֹּאַר וְגִבּוֹר חַיִל״:",1,0],[23,8,"עֲדִינוֹ הָעֶצְנִי. כְּשֶׁעוֹסֵק בַּתּוֹרָה, כּוֹרֵךְ וּמְקַשֵּׁר עַצְמוֹ כְּתוֹלַעַת, כְּמוֹ (איוב לח:לא): ״מַעֲדַנּוֹת כִּימָה״, וּכְשֶׁיּוֹצֵא לַמִּלְחָמָה, הָיָה קָשֶׁה כָּעֵץ, וְהוֹרֵג שְׁמוֹנֶה מֵאוֹת חָלָל בְּמִלְחָמָה אַחַת (מועד קטן טז ב):",2,0],[23,9,"בֶּן דּוֹדוֹ. כָּךְ שְׁמוֹ:",1,0],[23,9,"בִּשְׁלֹשָׁה הַגִּבֹּרִים. הַמְעֻלִּים שֶׁבַּגִּבּוֹרִים:",2,0],[23,9,"בְּחָרְפָם בַּפְּלִשְׁתִּים. תָּקְעוּ כַּף לְהִלָּחֵם בָּהֶם וּלְנַצְּחָם:",3,0],[23,10,"אַךְ לְפַשֵּׁט. תִּרְגֵּם יוֹנָתָן: ״לְחַלְּצָא קְטִילַיָּא״, לֹא הָיָה אִישׁ לְעָזְרוֹ לְהָרוֹג, אֶלָּא כֻּלָּם פּוֹשְׁטִים אַחֲרָיו אֶת הַחֲלָלִים:",1,0],[23,11,"הֲרָרִי. מִן הָהָר:",1,0],[23,11,"לַחַיָּה. לִגְדוּד כְּחַיּוֹת הַשָּׂדֶה:",2,0],[23,13,"מֵהַשְּׁלֹשִׁים רֹאשׁ. תִּרְגֵּם יוֹנָתָן: ״מִגִּבָּרֵי רֵישֵׁי מַשְׁרִיתָא״:",1,0],[23,14,"וּמַצַּב פְּלִשְׁתִּים אָז בֵּית לָחֶם. הַחַיִל הָיָה חוֹנֶה בְּעֵמֶק רְפָאִים, וְשָׁלְחוּ מַצָּב שֶׁלָּהֶם לְבֵית לָחֶם:",1,0],[23,15,"מִי יַשְׁקֵנִי מַיִם. אָמְרוּ רַבּוֹתֵינוּ (בבא קמא ס:): הֻצְרַךְ לִשְׁאוֹל שְׁאֵלָה מִסַּנְהֶדְרִין הַיּוֹשְׁבִים בְּשַׁעַר בֵּית לָחֶם:",1,0],[23,16,"וַיַּסֵּךְ אֹתָם לַה׳. כָּךְ אָמַר: מְקֻבְּלַנִי מִבֵּית דִּינוֹ שֶׁל שְׁמוּאֵל הָרָמָתִי, כָּל הַמּוֹסֵר עַצְמוֹ לְמִיתָה עַל דִּבְרֵי תוֹרָה, אֵין אוֹמְרִין שְׁמוּעָה מִפִּיו, וּמַאי וַיַּסֵּךְ אֹתָם לַה׳, דְּאַמְרִינְהוּ מִשְּׁמֵיהּ דִּגְמָרָא (בבא קמא סא.):",1,0],[23,17,"הֲדַם הָאֲנָשִׁים. לְשׁוֹן תְּמִיהָה:",1,0],[23,19,"וְעַד הַשְּׁלֹשָׁה לֹא בָא. (תרגום:) ״וְלִתְלַת גִּבָּרִין לָא מְטָא״:",1,0],[23,20,"אֶת שְׁנֵי אֲרִאֵל מוֹאָב. (תרגום:) ״יָת תְּרֵין רַבְרְבֵי מוֹאָב״. וְרַבּוֹתֵינוּ אָמְרוּ (ברכות יח ב): שֶׁלֹּא הִנִּיחַ כְּמוֹתוֹ, לֹא בְּמִקְדָּשׁ רִאשׁוֹן, וְלֹא בְּמִקְדָּשׁ שֵׁנִי:",1,0],[23,20,"אֲרִיאֵל מוֹאָב. עַל שֵׁם שֶׁבְּנָאוֹ שְׁלֹמֹה, שֶׁבָּא מֵרוּת הַמּוֹאֲבִיָּה:",2,0],[23,23,"מִן הַשְּׁלֹשִׁים. כָּל שְׁלֹשִׁים שֶׁבְּפָרָשָׁה זוֹ תִּרְגֵּם יוֹנָתָן: ״גִּבָּרַיָּא״:",1,0],[23,39,"שְׁלֹשִׁים וְשִׁבְעָה. וְאֵינָן מְנוּיִן כָּאן. וַאֲנִי אוֹמֵר: יוֹאָב לֹא הֻצְרַךְ לְהַזְכִּיר, שֶׁהוּא שַׂר הַצָּבָא, וּשְׁאָר שֶׁחָסְרוּ, שֶׁמָּא בְּנֵי (ישי) [צ״ל יָשָׁן יְהוֹנָתָן] שְׁלֹשָׁה אוֹ אַרְבָּעָה הָיוּ:",1,0],[24,1,"וַיֹּסֶף אַף ה׳ לַחֲרוֹת בְּיִשְׂרָאֵל. לֹא יָדַעְתִּי עַל מַה:",1,0],[24,1,"וַיָּסֶת. גֵּרָה:",2,0],[24,3,"כָּהֵם וְכָהֵם. כָּהֵם כִּפְלַיִם, וְכָהֵם שְׁנֵי כִּפְלַיִם, הֲרֵי אַרְבָּעָה כִּפְלַיִם, וְכֵן חוֹזֵר וְכוֹפֵל אֶת הַכְּפִילָה, עַד מֵאָה פְּעָמִים, נִמְצֵאת בִּרְכָתוֹ שֶׁל יוֹאָב יְתֵרָה עַל שֶׁל מֹשֶׁה שֶׁאָמַר (דברים א:יא): ״כָּכֶם אֶלֶף פְּעָמִים״, וְעוֹד, שֶׁבִּרְכָתוֹ שֶׁל מֹשֶׁה לִזְמַן מְרֻבֶּה, וְשֶׁל יוֹאָב מִיָּד, שֶׁנֶּאֱמַר בָּהּ: וְעֵינֵי אֲדֹנִי הַמֶּלֶךְ רוֹאוֹת:",1,0],[24,5,"הַגָּד וְאֶל יַעְזֵר. הִתְחִיל בִּבְנֵי גָד, לְפִי שֶׁהֵם גִּבּוֹרִים וְקָשִׁים, אָמַר: הַלְוַאי וְיִלָּחֲמוּ בִי, וִיעַכְּבוּ עַל יָדִי:",1,0],[24,6,"וְאֶל אֶרֶץ תַּחְתִּים חָדְשִׁי. מְקוֹם יִשּׁוּב חָדָשׁ, שֶׁאוּכְלוּסֵיהֶן מוּעָטִין, אוּלַי בְּתוֹךְ כָּךְ יִתְחָרֵט דָּוִד, וְיִשְׁלַח אֵלָיו שָׁלִיחַ שֶׁיַּחֲזֹר בּוֹ:",1,0],[24,6,"דָּנָה. בִּבְנֵי דָן:",2,0],[24,6,"יַעַן. שֵׁם הַמָּקוֹם:",3,0],[24,9,"מִסְפַּר מִפְקַד. אִם מִסְפָּר לָמָּה מִפְקָד, שְׁנֵי אַנְפִירָאוֹת עָשָׂה, גְּדוֹלָה וּקְטַנָּה, אָמַר אַרְאֶנּוּ אֶת הַקְּטַנָּה, וְאִם יִקְצֹף אַרְאֶנּוּ אֶת הַגְּדוֹלָה, לְכָךְ נֶאֱמַר מִפְקָד, לְשׁוֹן חִסָּרוֹן, כָּךְ נִדְרָשׁ בַּפְּסִקְתָּא:",1,0],[24,9,"וַתְּהִי יִשְׂרָאֵל. תָּשַׁשׁ כֹּחָן כִּנְקֵבָה:",2,0],[24,9,"שְׁמֹנֶה מֵאוֹת אֶלֶף. וּבְדִבְרֵי הַיָּמִים (דברי הימים א כא:ה) הוּא אוֹמֵר: ״אֶלֶף אֲלָפִים וּמֵאָה אֶלֶף״. בְּאַגָּדַת אֲמוֹרָאִים (ילקוט שמעוני על נ״ך רמז קסה) מָצִינוּ: אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, הַכְּתוּבִים מוֹסִיפִין כָּאן מַה שֶּׁחָסְרוּ כָּאן, אֵלּוּ שְׁנֵי שְׁבָטִים שֶׁלֹּא נִמְנוּ, שֶׁכָּךְ כְּתִיב בְּדִבְרֵי הַיָּמִים (דברי הימים א כא:ו): ״וְלֵוִי וּבִנְיָמִן לֹא פָקַד בְּתוֹכָם כִּי נִתְעַב דְּבַר הַמֶּלֶךְ אֶת יוֹאָב״. אָמַר יוֹאָב: בְּאֵלּוּ אֲנִי יָכוֹל לְהִשָּׁמֵט וְלוֹמַר, שֵׁבֶט לֵוִי אֵינוֹ נִמְנֶה בְּמִנְיַן שְׁאָר שְׁבָטִים כִּי אִם מִבֶּן חֹדֶשׁ וָמַעְלָה, וּבִנְיָמִין, דַּיּוֹ שֶׁנֶּחְסַר וְכָלָה בְּפִילֶגֶשׁ בַּגִּבְעָה. וּבִשְׁלֹשִׁים וּשְׁתַּיִם מִדּוֹת דְּרַבִּי אֱלִיעֶזֶר בְּנוֹ שֶׁל רַבִּי יוֹסֵי הַגְּלִילִי שָׁנִינוּ: כָּתוּב אֶחָד אוֹמֵר וַיְהִי כָל יִשְׂרָאֵל אֶלֶף אֲלָפִים וּמֵאָה אֶלֶף וִיהוּדָה אַרְבַּע מֵאוֹת וְשִׁבְעִים אֶלֶף, וְכָתוּב אֶחָד אוֹמֵר וַתְּהִי יִשְׂרָאֵל שְׁמֹנֶה מֵאוֹת אֶלֶף וְאִישׁ יְהוּדָה חֲמֵשׁ מֵאוֹת אֶלֶף, נִמְצָא בֵּינֵיהֶם שְׁלֹשׁ מֵאוֹת אֶלֶף, אֵלּוּ שְׁלֹשׁ מֵאוֹת אֶלֶף מַה טִּיבָן, בָּא הַכָּתוּב הַשְּׁלִישִׁי וְהִכְרִיעַ (דברי הימים א כז:א): ״וּבְנֵי יִשְׂרָאֵל לְמִסְפָּרָם רָאשֵׁי הָאָבוֹת וְשָׂרֵי הָאֲלָפִים וְהַמֵּאוֹת וְשֹׁטְרֵיהֶם הַמְשָׁרְתִים אֶת הַמֶּלֶךְ לְכָל דְּבַר הַמַּחְלֹקֶת הַבָּאָה וְהַיּוֹצֵאת חֹדֶשׁ בְּחֹדֶשׁ לְכָל חָדְשֵׁי הַשָּׁנָה הַמַּחְלֹקֶת הָאַחַת עֶשְׂרִים וְאַרְבָּעָה אָלֶף״, מְלַמֵּד שֶׁאֵלּוּ שְׁלֹשׁ מֵאוֹת אֶלֶף הָיוּ הַכְּתוּבִים בְּנִמּוּסוֹ שֶׁל מֶלֶךְ, וְלֹא הָיוּ צְרִיכִין לִמָּנוֹת, כֵּיצַד, עֶשְׂרִים וְאַרְבָּעָה אֶלֶף לִשְׁנֵים עָשָׂר, הֲרֵי כָּאן מָאתַיִם וּשְׁמוֹנִים אֶלֶף וּשְׁמוֹנַת אֲלָפִים, נִשְׁתַּיְּרוּ שְׁנֵים עָשָׂר אֶלֶף, הֵן הֵן נְשִׂיאֵי יִשְׂרָאֵל:",3,0],[24,12,"שָׁלֹשׁ אָנֹכִי נוֹטֵל עָלֶיךָ. אַחַת מִשָּׁלֹשׁ, וְכֵן (שמואל א יח:כא): ״בִּשְׁתַּיִם תִּתְחַתֵּן בִּי הַיּוֹם״, בְּאַחַת מִשְּׁתַּיִם. שָׁלֹשׁ אֲנִי נוֹטֵל עָלֶיךָ, כְּנֶגֶד שָׁלֹשׁ שֶׁהִטַּלְתָּ עַל שָׁאוּל, (שמואל א כו:י): ״כִּי אִם ה׳ יִגָּפֶנּוּ, אוֹ יוֹמוֹ יָבֹא וָמֵת, אוֹ בַמִּלְחָמָה יֵרֵד וְנִסְפָּה״:",1,0],[24,14,"צַר לִי מְאֹד. הַקְּטַנָּה שֶׁבָּהֶם קָשָׁה מְאֹד:",1,0],[24,14,"נִפְּלָה נָּא בְיַד ה׳. הַדֶּבֶר, וְלֹא הַחֶרֶב וְהָרָעָב, שֶׁגַּם הוּא מָסוּר לַעֲשִׁירִים אוֹצְרֵי פֵּירוֹת. אָמַר רַבִּי אֲלֶכְּסַנְדְּרִי: אָמַר דָּוִד, אִם אֲנִי בּוֹרֵר לִי הַחֶרֶב עַכְשָׁיו, יִשְׂרָאֵל אוֹמְרִים הוּא בּוֹטֵחַ בְּגִבּוֹרָיו, שֶׁהוּא לֹא יָמוּת וְהָאֲחֵרִים יָמוּתוּ, וְאִם אֲנִי בּוֹרֵר הָרָעָב, יֹאמְרוּ בּוֹטֵחַ הוּא בְּעָשְׁרוֹ, אֶבְרַר לִי דֶּבֶר שֶׁהַכֹּל שָׁוִין בּוֹ (ראה ילקוט שמעוני רמז קסה):",2,0],[24,15,"מֵהַבֹּקֶר וְעַד עֵת מוֹעֵד. (תרגום:) ״מֵעִדָּן דְּמִתְנְכֵיס תְּמִידָא וְעַד דְּמִתְסַק״:",1,0],[24,16,"הַיְבֻסִי. שַׂר מְצוּדַת צִיּוֹן הָיָה, שֶׁשָּׁמָה יְבוּסִי:",1,0],[24,20,"וַיַּשְׁקֵף אֲרַוְנָה. מִתְחַבֵּא הָיָה מִפְּנֵי הַמַּלְאָךְ, כָּךְ כָּתוּב בְּדִבְרֵי הַיָּמִים (דברי הימים א כא:כ):",1,0],[24,22,"וְהַמֹּרִגִּים. כְּלִי עֵץ מָלֵא חֲרִיצִין, וְכָבֵד הוּא, וּמַעֲבִירִין אוֹתוֹ עַל הַקַּשׁ תָּמִיד, וּמְחַתְּכוֹ לִהְיוֹת תֶּבֶן לְמַאֲכַל בְּהֵמוֹת:",1,0],[24,23,"אֲרַוְנָה הַמֶּלֶךְ. שַׂר הַיְבוּסִי הָיָה:",1,0],[24,24,"שְׁקָלִים חֲמִשִּׁים. וּבְדִבְרֵי הַיָּמִים (דברי הימים א כא:כה) הוּא אוֹמֵר, ״שִׁקְלֵי זָהָב מִשְׁקַל שֵׁשׁ מֵאוֹת״, הָא כֵּיצַד, גָּבָה חֲמִשִּׁים שְׁקָלִים כֶּסֶף מִכָּל שֵׁבֶט וְשֵׁבֶט, הֲרֵי שֵׁשׁ מֵאוֹת, וְנָתַן לוֹ כֶּסֶף בִּדְמֵי הַזָּהָב. וְכֵן שָׁנִינוּ בְּסוֹף שְׁחִיטַת קָדָשִׁים (זבחים קטז ב): גָּבָה כֶּסֶף בְּשֵׁשׁ מֵאוֹת כֶּסֶף בְּשִׁקְלֵי זָהָב. וְכֵן שָׁנִינוּ בְּסִפְרִי. חסלת ספר שמואל:",1,0]]);
